 * Turns a parsed document tree into the two output formats the CLI
 * supports: canonical JSON and the flat `keys` listing.
 */

/** Compares two strings by Unicode code point, not by UTF-16 code unit. */
function compareByCodePoint(a, b) {
  const ai = Array.from(a)
  const bi = Array.from(b)
  const len = Math.min(ai.length, bi.length)
  for (let i = 0; i < len; i++) {
    const ca = ai[i].codePointAt(0)
    const cb = bi[i].codePointAt(0)
    if (ca !== cb) return ca - cb
  }
  return ai.length - bi.length
}

