  return Object.keys(children).sort(compareByCodePoint)
}

function toPlain(node) {
  switch (node.type) {
    case 'table': {
      const obj = {}
      for (const key of sortedKeys(node.children)) obj[key] = toPlain(node.children[key])
      return obj
    }
    case 'array-of-tables':
      return node.items.map(toPlain)
    case 'array':
      return node.items.map(toPlain)
    default:
      return node.value
  }
}

export function toJson(root) {
  return `${JSON.stringify(toPlain(root), null, 2)}\n`
}

function typeOf(node) {
  if (node.type === 'array-of-tables') return 'array'
  return node.type
}

function emitNode(node, path, out) {
  out.push(`${path} ${typeOf(node)}`)
  if (node.type === 'table') {
    emitChildren(node, path, out)
  } else if (node.type === 'array' || node.type === 'array-of-tables') {
    node.items.forEach((item, i) => emitNode(item, `${path}[${i}]`, out))
  }
}

function emitChildren(tableNode, basePath, out) {
  for (const key of sortedKeys(tableNode.children)) {
    const child = tableNode.children[key]
    const path = basePath ? `${basePath}.${key}` : key
    emitNode(child, path, out)
  }
}

export function toKeys(root) {
  const out = []
  emitChildren(root, '', out)
  return out.length > 0 ? `${out.join('\n')}\n` : ''
