 * Line-level diffing of a document against a base document.
 */

/**
 * Computes the changes needed to turn `base` into `side`, using a longest
 * common subsequence over whole lines. When several subsequences of maximal
 * length exist, the one whose matches come earliest is chosen: walking both
 * documents from the start, a match is taken whenever the current lines are
 * equal, and otherwise the side whose remaining subsequence is at least as
 * long as the other's is advanced, preferring to advance the base on a tie.
 *
 * Returns changes ordered by base position, each a run of base lines
 * (`start` to `end`, exclusive) replaced by `lines` from `side`. An
 * insertion has `start === end`; a deletion has an empty `lines`.
 */
export function computeChanges(base, side) {
  const m = base.length
  const n = side.length

  // dp[i][j] holds the LCS length of base[i:] and side[j:].
  const dp = new Array(m + 1)
  for (let i = 0; i <= m; i++) dp[i] = new Int32Array(n + 1)
  for (let i = m - 1; i >= 0; i--) {
    for (let j = n - 1; j >= 0; j--) {
      dp[i][j] = base[i] === side[j] ? dp[i + 1][j + 1] + 1 : Math.max(dp[i + 1][j], dp[i][j + 1])
    }
  }

  const changes = []
  let i = 0
  let j = 0
  let lastI = 0
  let lastJ = 0
  while (i < m && j < n) {
    if (base[i] === side[j]) {
      if (i > lastI || j > lastJ) changes.push({ start: lastI, end: i, lines: side.slice(lastJ, j) })
      i++
      j++
      lastI = i
      lastJ = j
    } else if (dp[i + 1][j] >= dp[i][j + 1]) {
      i++
    } else {
      j++
    }
  }
  if (m > lastI || n > lastJ) changes.push({ start: lastI, end: m, lines: side.slice(lastJ, n) })
  return changes
}
"}

