 * Builds three-way merge regions from mine's and theirs' changes against a
 * shared base.
 */

function arraysEqual(a, b) {
  if (a.length !== b.length) return false
  for (let i = 0; i < a.length; i++) if (a[i] !== b[i]) return false
  return true
}

/**
 * Reconstructs one side's lines for a region, given the base document, the
 * region's base bounds and that side's own changes within the region. Base
 * lines outside those changes are carried over unchanged.
 */
function applySide(base, start, end, changes) {
  if (changes.length === 0) return base.slice(start, end)
  const result = []
  let pos = start
  for (const change of changes) {
    if (change.start > pos) result.push(...base.slice(pos, change.start))
    result.push(...change.lines)
    pos = change.end
  }
  if (pos < end) result.push(...base.slice(pos, end))
  return result
}

/**
 * Groups mine's and theirs' changes into regions ordered by base position,
 * merging changes that overlap or touch, and resolves each region against
 * the rule: equal sides resolve to mine (as `both`); a side that made no
 * effective change yields to the other; otherwise the region conflicts.
 * The base stretches a region does not cover form `stable` regions.
 */
export function buildRegions(base, mineChanges, theirsChanges) {
  const tagged = [
    ...mineChanges.map(change => ({ ...change, side: 'mine' })),
    ...theirsChanges.map(change => ({ ...change, side: 'theirs' })),
  ]
  tagged.sort((a, b) => a.start - b.start || (a.side === 'mine' ? -1 : 1) - (b.side === 'mine' ? -1 : 1))

  const regions = []
  let basePos = 0
  let index = 0
  while (index < tagged.length) {
    let start = tagged[index].start
    let end = tagged[index].end
    const absorbed = [tagged[index]]
    index++
    while (index < tagged.length && tagged[index].start <= end) {
      absorbed.push(tagged[index])
      end = Math.max(end, tagged[index].end)
      index++
    }

    if (start > basePos) regions.push({ type: 'stable', lines: base.slice(basePos, start) })
    regions.push(resolveRegion(base, start, end, absorbed))
    basePos = end
  }
  if (basePos < base.length) regions.push({ type: 'stable', lines: base.slice(basePos) })
  return regions
}

function resolveRegion(base, start, end, absorbed) {
  const baseLines = base.slice(start, end)
  const mineLines = applySide(base, start, end, absorbed.filter(change => change.side === 'mine'))
  const theirsLines = applySide(base, start, end, absorbed.filter(change => change.side === 'theirs'))

  if (arraysEqual(mineLines, theirsLines)) return { type: 'both', lines: mineLines }
  if (arraysEqual(mineLines, baseLines)) return { type: 'theirs', lines: theirsLines }
  if (arraysEqual(theirsLines, baseLines)) return { type: 'mine', lines: mineLines }
  return { type: 'conflict', mine: mineLines, base: baseLines, theirs: theirsLines }
}
"}

