/**
 * The command. `node src/cli.js merge`, `node src/cli.js merge2` and
 * `node src/cli.js regions` each read three documents from standard input and
 * report the three-way merge of the second into the first and the third.
 */

import { computeChanges } from './diff.js'
import { buildRegions } from './regions.js'

const MODES = new Set(['merge', 'merge2', 'regions'])

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function parseInput(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const docs = [[]]
  for (const line of lines) {
    if (line === '%%%') docs.push([])
    else docs[docs.length - 1].push(line)
  }
  if (docs.length !== 3) fail('expected three parts separated by %%%')
  return docs
}

function readStdin() {
  const chunks = []
  const fd = 0
  const buffer = Buffer.alloc(65536)
  const fs = require('node:fs')
  while (true) {
    let bytesRead
    try {
      bytesRead = fs.readSync(fd, buffer, 0, buffer.length, null)
    } catch (error) {
      if (error.code === 'EAGAIN') continue
      if (error.code === 'EOF') break
      throw error
    }
    if (bytesRead === 0) break
    chunks.push(Buffer.from(buffer.subarray(0, bytesRead)))
  }
  return Buffer.concat(chunks).toString('utf8')
}

function renderMerge(regions, includeBase) {
  const out = []
  let conflict = false
  for (const region of regions) {
    if (region.type === 'conflict') {
      conflict = true
      out.push('<<<<<<< mine', ...region.mine)
      if (includeBase) out.push('||||||| base', ...region.base)
      out.push('=======', ...region.theirs, '>>>>>>> theirs')
    } else {
      out.push(...region.lines)
    }
  }
  return { text: out.length > 0 ? `${out.join('\n')}\n` : '', conflict }
}

function renderRegions(regions) {
  const out = []
  let conflict = false
  for (const region of regions) {
    if (region.type === 'conflict') {
      conflict = true
      out.push(`conflict mine=${region.mine.length} base=${region.base.length} theirs=${region.theirs.length}`)
    } else {
      out.push(`${region.type} ${region.lines.length}`)
    }
  }
  return { text: out.length > 0 ? `${out.join('\n')}\n` : '', conflict }
}

function main() {
  const mode = process.argv[2]
  if (process.argv.length !== 3 || !MODES.has(mode)) fail('usage: cli.js merge|merge2|regions')

  const input = readStdin()
  const [mine, base, theirs] = parseInput(input)

  const mineChanges = computeChanges(base, mine)
  const theirsChanges = computeChanges(base, theirs)
  const regions = buildRegions(base, mineChanges, theirsChanges)

  const { text, conflict } =
    mode === 'regions' ? renderRegions(regions) : renderMerge(regions, mode === 'merge')

  process.stdout.write(text)
  process.exit(conflict ? 1 : 0)
}

main()
"}

