 * Phase-2 (semantic) resolution: walks an AST produced by lineSyntax.js
 * against the growing document tree, creating tables on the way and
 * reporting the structural errors that depend on prior state.
 */
import { DocError } from './errors.js'

export function makeTable() {
  return { kind: 'table', entries: new Map(), headerDefined: false }
}

/**
 * Walks all but the last segment of a dotted name from `container`,
 * creating intermediate tables as needed and following an array of tables
 * to its last element. Returns the table the final segment lives in, and
 * the root-counted path leading to it.
 */
function walkIntermediateSegments(container, names, basePath, lineNo) {
  let node = container
  const path = basePath.slice()
  for (let i = 0; i < names.length - 1; i++) {
    const name = names[i]
    path.push(name)
    let entry = node.entries.get(name)
    if (entry === undefined) {
      entry = makeTable()
      node.entries.set(name, entry)
    }
    if (entry.kind === 'array-of-tables') {
      entry = entry.items[entry.items.length - 1]
    } else if (entry.kind !== 'table') {
      throw new DocError(lineNo, `${path.join('.')} is not a table`)
    }
    node = entry
  }
  return { node, path }
}

function materializeValue(ast, path, lineNo) {
  if (ast.kind === 'array') {
    return { kind: 'array', items: ast.items.map((it) => materializeValue(it, path, lineNo)) }
  }
  if (ast.kind === 'inlinetable') {
    const table = makeTable()
    for (const pair of ast.pairs) {
      materializeAssignment(table, path, pair.names, pair.value, lineNo)
    }
    return table
  }
  return ast // scalar node: already {kind, value}
}

export function materializeAssignment(container, basePath, names, valueAst, lineNo) {
  const { node, path } = walkIntermediateSegments(container, names, basePath, lineNo)
  const finalName = names[names.length - 1]
  const fullPath = path.concat(finalName)
  if (node.entries.has(finalName)) {
    throw new DocError(lineNo, `key ${fullPath.join('.')} is defined twice`)
  }
  const value = materializeValue(valueAst, fullPath, lineNo)
  node.entries.set(finalName, value)
}

export function materializeHeader(root, names, lineNo) {
  const { node, path } = walkIntermediateSegments(root, names, [], lineNo)
  const finalName = names[names.length - 1]
  const fullPath = path.concat(finalName)
  const existing = node.entries.get(finalName)
  if (existing === undefined) {
    const table = makeTable()
    table.headerDefined = true
    node.entries.set(finalName, table)
    return { table, path: fullPath }
  }
  if (existing.kind === 'table') {
    if (existing.headerDefined) {
      throw new DocError(lineNo, `table ${fullPath.join('.')} is defined twice`)
    }
    existing.headerDefined = true
    return { table: existing, path: fullPath }
  }
  throw new DocError(lineNo, `${fullPath.join('.')} is not a table`)
}

export function materializeHeaderArray(root, names, lineNo) {
  const { node, path } = walkIntermediateSegments(root, names, [], lineNo)
  const finalName = names[names.length - 1]
  const fullPath = path.concat(finalName)
  let arr = node.entries.get(finalName)
  if (arr === undefined) {
    arr = { kind: 'array-of-tables', items: [] }
    node.entries.set(finalName, arr)
  } else if (arr.kind !== 'array-of-tables') {
    throw new DocError(lineNo, `${fullPath.join('.')} is not an array of tables`)
  }
  const table = makeTable()
  arr.items.push(table)
  return { table, path: fullPath }
}
