{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e3-attempts-t5-20260919T123108Z/cell-1Vc82q/src/parser.js","content":"/** Parses a whole configuration document into its document tree. */
import { parseLine } from './lineSyntax.js'
import { makeTable, materializeAssignment, materializeHeader, materializeHeaderArray } from './materialize.js'

export function parseDocument(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const root = makeTable()
  let current = root
  let currentPath = []

  for (let idx = 0; idx < lines.length; idx++) {
    const lineNo = idx + 1
    const ast = parseLine(lines[idx], lineNo)
    if (ast === null) continue

    if (ast.type === 'header') {
      const { table, path } = materializeHeader(root, ast.names, lineNo)
      current = table
      currentPath = path
    } else if (ast.type === 'headerArray') {
      const { table, path } = materializeHeaderArray(root, ast.names, lineNo)
      current = table
      currentPath = path
    } else {
      materializeAssignment(current, currentPath, ast.names, ast.value, lineNo)
    }
  }

  return root
}
"}

