{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e3-attempts-t5-20260919T123108Z/cell-1cFW9H/src/parse.js","content":"/**
 * Parses the election description read from standard input into a list of
 * candidate names and a list of ballots, or throws a `ParseError` describing
 * the first line that fails to conform to the format.
 */

const NAME_RE = /^[A-Za-z0-9_-]+$/
const COUNT_RE = /^[1-9][0-9]*$/

export class ParseError extends Error {
  constructor(message, line) {
    super(line === undefined ? `error: ${message}` : `error: line ${line}: ${message}`)
  }
}

export function parseElection(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const candidates = []
  const candidateSet = new Set()
  let candidatesDeclared = false
  const ballots = []

  for (let i = 0; i < lines.length; i++) {
    const lineNumber = i + 1
    const trimmed = lines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue

    const tokens = trimmed.split(/\s+/)
    const directive = tokens[0]

    if (directive === 'candidates') {
      if (candidatesDeclared) {
        throw new ParseError('candidates must be declared once, before any ballot', lineNumber)
      }
      if (tokens.length < 2) {
        throw new ParseError('expected candidates <name>...', lineNumber)
      }
      for (const name of tokens.slice(1)) {
        if (!NAME_RE.test(name)) {
          throw new ParseError(`invalid candidate name ${name}`, lineNumber)
        }
        if (candidateSet.has(name)) {
          throw new ParseError(`candidate ${name} is declared twice`, lineNumber)
        }
        candidateSet.add(name)
        candidates.push(name)
      }
      candidatesDeclared = true
    } else if (directive === 'ballot') {
      if (!candidatesDeclared) {
        throw new ParseError('candidates must be declared once, before any ballot', lineNumber)
      }
      if (tokens.length < 3) {
        throw new ParseError('expected ballot <count> <candidate>...', lineNumber)
      }
      const countToken = tokens[1]
      if (!COUNT_RE.test(countToken)) {
        throw new ParseError('count must be a positive integer', lineNumber)
      }
      const count = Number(countToken)
      const ranking = []
      const seen = new Set()
      for (const name of tokens.slice(2)) {
        if (!candidateSet.has(name)) {
          throw new ParseError(`unknown candidate ${name}`, lineNumber)
        }
        if (seen.has(name)) {
          throw new ParseError(`candidate ${name} is repeated`, lineNumber)
        }
        seen.add(name)
        ranking.push(name)
      }
      ballots.push({ count, ranking })
    } else {
      throw new ParseError(`unknown directive ${directive}`, lineNumber)
    }
  }

  if (!candidatesDeclared) {
    throw new ParseError('no candidates')
  }

  return { candidates, ballots }
}
"}

