{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e3-attempts-t5-20260919T123108Z/cell-1cFW9H/src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js rounds` prints every round of the instant-runoff
 * count read from standard input, and `node src/cli.js tally` prints only how
 * many rounds ran and who won.
 */

import { parseElection, ParseError } from './parse.js'
import { runElection } from './election.js'

function readStdin() {
  const chunks = []
  const fd = 0
  const buffer = Buffer.alloc(65536)
  const fs = require('node:fs')
  for (;;) {
    let bytesRead
    try {
      bytesRead = fs.readSync(fd, buffer, 0, buffer.length, null)
    } catch (err) {
      if (err.code === 'EAGAIN') continue
      if (err.code === 'EOF') break
      throw err
    }
    if (bytesRead === 0) break
    chunks.push(Buffer.from(buffer.subarray(0, bytesRead)))
  }
  return Buffer.concat(chunks).toString('utf8')
}

function fail(message) {
  process.stderr.write(`${message}\n`)
  process.exit(2)
}

function main() {
  const mode = process.argv[2]
  if (process.argv.length !== 3 || (mode !== 'rounds' && mode !== 'tally')) {
    fail('error: usage: cli.js rounds|tally')
    return
  }

  const input = readStdin()

  let election
  try {
    election = parseElection(input)
  } catch (err) {
    if (err instanceof ParseError) {
      fail(err.message)
      return
    }
    throw err
  }

  const output = []
  let roundCount = 0
  let winner = null

  runElection(election, ({ votes, exhausted, eliminated, winner: roundWinner }) => {
    roundCount++
    if (mode === 'rounds') {
      const parts = [...votes].map(([name, count]) => `${name}=${count}`)
      parts.push(`exhausted=${exhausted}`)
      output.push(`round ${roundCount}: ${parts.join(' ')}`)
      if (eliminated !== null) output.push(`eliminated ${eliminated}`)
    }
    if (roundWinner !== null) winner = roundWinner
  })

  if (mode === 'tally') {
    output.push(`rounds ${roundCount}`)
  }
  output.push(winner === null ? 'no winner' : `winner ${winner}`)

  process.stdout.write(output.join('\n') + '\n')
}

main()
"}

