/**
 * Finds a dependency cycle, if one exists, by running a depth-first search
 * from each task in ascending name order and walking each task's
 * dependencies in ascending order. Returns the names from the re-entered
 * task through the search stack back to itself, or `null` if the graph is
 * acyclic.
 */
function findCycle(tasks, adjacency) {
  const state = new Map()
  for (const name of tasks.keys()) state.set(name, 'unvisited')
  const stack = []

  function visit(name) {
    state.set(name, 'active')
    stack.push(name)
    for (const dep of adjacency.get(name)) {
      const depState = state.get(dep)
      if (depState === 'active') {
        const start = stack.indexOf(dep)
        return [...stack.slice(start), dep]
      }
      if (depState === 'unvisited') {
        const cycle = visit(dep)
        if (cycle) return cycle
      }
    }
    state.set(name, 'done')
    stack.pop()
    return null
  }

  for (const name of [...tasks.keys()].sort()) {
    if (state.get(name) === 'unvisited') {
      const cycle = visit(name)
      if (cycle) return cycle
    }
  }
  return null
}

/** Throws a `CliError` with code 3 when the graph has a dependency cycle. */
export function checkAcyclic(tasks, adjacency) {
  const cycle = findCycle(tasks, adjacency)
  if (cycle) throw new CliError(3, `error: cycle: ${cycle.join(' -> ')}`)
}

/**
 * Computes each task's start, finish and wave depth under unlimited
 * parallelism: a task starts once every dependency has finished, and its
 * depth is one past the deepest dependency's depth.
 */
export function computeTimings(tasks, adjacency) {
  const start = new Map()
  const finish = new Map()
  const depth = new Map()

  function compute(name) {
    if (finish.has(name)) return
    let s = 0
    let d = 0
    for (const dep of adjacency.get(name)) {
      compute(dep)
      s = Math.max(s, finish.get(dep))
      d = Math.max(d, depth.get(dep) + 1)
    }
    start.set(name, s)
    finish.set(name, s + tasks.get(name))
    depth.set(name, d)
  }

  for (const name of tasks.keys()) compute(name)
  return { start, finish, depth }
}

/**
 * Computes each task's scheduling priority: the cost of the longest chain
 * of costs starting at that task and following its dependents down to a
 * task nothing depends on.
 */
export function computePriorities(tasks, adjacency) {
  const dependents = new Map()
  for (const name of tasks.keys()) dependents.set(name, [])
  for (const [name, deps] of adjacency) {
    for (const dep of deps) dependents.get(dep).push(name)
  }

  const priority = new Map()
  function compute(name) {
    if (priority.has(name)) return priority.get(name)
    let best = 0
    for (const dependent of dependents.get(name)) best = Math.max(best, compute(dependent))
    const value = tasks.get(name) + best
    priority.set(name, value)
    return value
  }

  for (const name of tasks.keys()) compute(name)
  return priority
}
"}

