{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e3-attempts-t5-20260919T123108Z/cell-8DLu4R/src/scheduler.js","content":"import { computePriorities } from './graph.js'

/**
 * Simulates the build graph on a fixed number of workers. At every instant,
 * while a worker is free and some task is ready (every dependency has
 * already finished), the ready task with the greatest priority (ties broken
 * by ascending name) starts on the free worker with the smallest index.
 * Returns each worker's run of `{ name, start, finish }` entries in the
 * order they ran, plus the overall makespan.
 */
export function pack(tasks, adjacency, workerCount) {
  const priority = computePriorities(tasks, adjacency)
  const names = [...tasks.keys()]
  const remaining = new Set(names)
  const finish = new Map()
  const freeAt = new Array(workerCount).fill(0)
  const runs = Array.from({ length: workerCount }, () => [])

  function isReady(name, current) {
    for (const dep of adjacency.get(name)) {
      const depFinish = finish.get(dep)
      if (depFinish === undefined || depFinish > current) return false
    }
    return true
  }

  function pickReady(current) {
    let best = null
    for (const name of remaining) {
      if (!isReady(name, current)) continue
      if (best === null) {
        best = name
        continue
      }
      if (priority.get(name) > priority.get(best) || (priority.get(name) === priority.get(best) && name < best)) {
        best = name
      }
    }
    return best
  }

  let current = 0
  while (remaining.size > 0) {
    let progressed = true
    while (progressed) {
      progressed = false
      for (let i = 0; i < workerCount; i++) {
        if (freeAt[i] > current) continue
        const chosen = pickReady(current)
        if (chosen === null) break
        const taskFinish = current + tasks.get(chosen)
        runs[i].push({ name: chosen, start: current, finish: taskFinish })
        freeAt[i] = taskFinish
        finish.set(chosen, taskFinish)
        remaining.delete(chosen)
        progressed = true
        break
      }
    }
    if (remaining.size === 0) break
    let next = Infinity
    for (const t of freeAt) if (t > current && t < next) next = t
    current = next
  }

  const makespan = finish.size > 0 ? Math.max(...finish.values()) : 0
  return { runs, makespan }
}
"}

