/**
 * The command. `node src/cli.js waves`, `node src/cli.js explain` and
 * `node src/cli.js pack <workers>` each report on the build graph read from
 * standard input.
 */

import { readFileSync } from 'node:fs'
import { CliError } from './errors.js'
import { parseGraph } from './parser.js'
import { checkAcyclic, computeTimings } from './graph.js'
import { pack } from './scheduler.js'

const USAGE = 'error: usage: cli.js waves|explain|pack <workers>'
const WORKERS_RE = /^[1-9][0-9]*$/

function parseArgs(argv) {
  if (argv.length === 1 && (argv[0] === 'waves' || argv[0] === 'explain')) {
    return { mode: argv[0] }
  }
  if (argv.length === 2 && argv[0] === 'pack') {
    if (!WORKERS_RE.test(argv[1])) throw new CliError(2, 'error: workers must be a positive integer')
    return { mode: 'pack', workers: parseInt(argv[1], 10) }
  }
  throw new CliError(2, USAGE)
}

function runWaves(tasks, adjacency, out) {
  const { finish, depth } = computeTimings(tasks, adjacency)
  const names = [...tasks.keys()].sort()
  const maxDepth = names.reduce((max, name) => Math.max(max, depth.get(name)), -1)
  for (let d = 0; d <= maxDepth; d++) {
    const wave = names.filter((name) => depth.get(name) === d)
    out.push(`wave ${d}: ${wave.join(' ')}`)
  }
  const total = names.length > 0 ? Math.max(...names.map((name) => finish.get(name))) : 0
  out.push(`total ${total}`)
}

function runExplain(tasks, adjacency, out) {
  const { start, finish, depth } = computeTimings(tasks, adjacency)
  const names = [...tasks.keys()].sort()
  for (const name of names) {
    out.push(`${name} start=${start.get(name)} finish=${finish.get(name)} depth=${depth.get(name)}`)
  }
  const total = names.length > 0 ? Math.max(...names.map((name) => finish.get(name))) : 0
  out.push(`total ${total}`)
}

function runPack(tasks, adjacency, workers, out) {
  const { runs, makespan } = pack(tasks, adjacency, workers)
  runs.forEach((run, i) => {
    const items = run.map((entry) => ` ${entry.name}@${entry.start}-${entry.finish}`).join('')
    out.push(`worker ${i}:${items}`)
  })
  out.push(`makespan ${makespan}`)
}

function main() {
  const args = parseArgs(process.argv.slice(2))
  const input = readFileSync(0, 'utf8')
  const { tasks, adjacency } = parseGraph(input)
  checkAcyclic(tasks, adjacency)

  const out = []
  if (args.mode === 'waves') runWaves(tasks, adjacency, out)
  else if (args.mode === 'explain') runExplain(tasks, adjacency, out)
  else runPack(tasks, adjacency, args.workers, out)

  process.stdout.write(out.join('\n') + '\n')
}

try {
  main()
} catch (error) {
  if (error instanceof CliError) {
    process.stderr.write(error.message + '\n')
    process.exit(error.code)
  }
  throw error
}
"}

