function main() {
  const args = parseArgs(process.argv.slice(2))
  const input = readFileSync(0, 'utf8')
  const { tasks, adjacency } = parseGraph(input)
  checkAcyclic(tasks, adjacency)

  const out = []
  if (args.mode === 'waves') runWaves(tasks, adjacency, out)
  else if (args.mode === 'explain') runExplain(tasks, adjacency, out)
  else runPack(tasks, adjacency, args.workers, out)

  process.stdout.write(out.join('\n') + '\n')
}

try {
  main()
} catch (error) {
  if (error instanceof CliError) {
    process.stderr.write(error.message + '\n')
    process.exit(error.code)
  }
  throw error
}
"}

