{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e3-attempts-t5-20260919T123108Z/cell-BjKgnS/src/cycle.js","content":"/**
 * Cycle detection for the dependency graph. Runs a depth-first search from
 * each task in ascending name order, walking each task's dependencies in
 * ascending name order, and reports the first cycle re-entered.
 */

export function findCycle({ tasks, deps }) {
  const names = [...tasks.keys()].sort()
  const state = new Map()
  const stack = []

  function visit(node) {
    state.set(node, 'active')
    stack.push(node)
    const children = [...(deps.get(node) || [])].sort()
    for (const child of children) {
      const childState = state.get(child)
      if (childState === 'active') {
        const idx = stack.indexOf(child)
        return [...stack.slice(idx), child]
      }
      if (childState !== 'done') {
        const found = visit(child)
        if (found) return found
      }
    }
    state.set(node, 'done')
    stack.pop()
    return null
  }

  for (const start of names) {
    if (state.get(start) === 'done') continue
    const found = visit(start)
    if (found) return found
  }
  return null
}
"}

{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e3-attempts-t5-20260919T123108Z/cell-BjKgnS/src/schedule.js","content":"/**
 * Computes the unlimited-worker schedule: each task's start, finish and
 * wave depth, plus the overall makespan. Assumes the graph is acyclic.
 */

export function computeSchedule({ tasks, deps }) {
  const start = new Map()
  const finish = new Map()
  const depth = new Map()

  function compute(name) {
    if (finish.has(name)) return
    const ds = deps.get(name)
    let s = 0
    let d = 0
    if (ds) {
      for (const dep of ds) {
        compute(dep)
        if (finish.get(dep) > s) s = finish.get(dep)
        if (depth.get(dep) + 1 > d) d = depth.get(dep) + 1
      }
    }
    start.set(name, s)
    finish.set(name, s + tasks.get(name))
    depth.set(name, d)
  }

  for (const name of tasks.keys()) compute(name)

  return { start, finish, depth }
}

export function totalOf(finish) {
  let total = 0
  for (const f of finish.values()) if (f > total) total = f
  return total
}

export function formatWaves({ depth, finish }) {
  const groups = new Map()
  for (const [name, d] of depth) {
    if (!groups.has(d)) groups.set(d, [])
    groups.get(d).push(name)
  }
  const maxDepth = groups.size ? Math.max(...groups.keys()) : -1
  let out = ''
  for (let k = 0; k <= maxDepth; k++) {
    const names = (groups.get(k) || []).sort()
    out += `wave ${k}: ${names.join(' ')}\n`
  }
  out += `total ${totalOf(finish)}\n`
  return out
}

export function formatExplain({ start, finish, depth }) {
  const names = [...start.keys()].sort()
  let out = ''
  for (const name of names) {
    out += `${name} start=${start.get(name)} finish=${finish.get(name)} depth=${depth.get(name)}\n`
  }
  out += `total ${totalOf(finish)}\n`
  return out
}
"}

{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e3-attempts-t5-20260919T123108Z/cell-BjKgnS/src/pack.js","content":"/**
 * Simulates the build graph on a fixed number of workers, greedily starting
 * the highest-priority ready task on the lowest-indexed free worker at each
 * instant. Priority is the cost of the longest chain of costs starting at
 * a task and running forward through its dependents to a task nothing
 * depends on.
 */

function computePriorities(tasks, dependents) {
  const priority = new Map()
  const visiting = new Set()

  function compute(name) {
    if (priority.has(name)) return priority.get(name)
    visiting.add(name)
    let best = 0
    for (const dependent of dependents.get(name) || []) {
      const p = compute(dependent)
      if (p > best) best = p
    }
    visiting.delete(name)
    const value = tasks.get(name) + best
    priority.set(name, value)
    return value
  }

  for (const name of tasks.keys()) compute(name)
  return priority
}

export function packWorkers({ tasks, deps }, workerCount) {
  const dependents = new Map()
  for (const [name, ds] of deps) {
    for (const d of ds) {
      if (!dependents.has(d)) dependents.set(d, new Set())
      dependents.get(d).add(name)
    }
  }

  const priority = computePriorities(tasks, dependents)

  const finishTime = new Map()
  const remaining = new Set(tasks.keys())
  const workerFreeAt = new Array(workerCount).fill(0)
  const workerLog = Array.from({ length: workerCount }, () => [])

  let time = 0

  const isReady = (name, at) => {
    const ds = deps.get(name)
    if (!ds) return true
    for (const d of ds) {
      if (!finishTime.has(d) || finishTime.get(d) > at) return false
    }
    return true
  }

  while (remaining.size > 0) {
    let startedSomething = true
    while (startedSomething) {
      startedSomething = false

      let freeIdx = -1
      for (let i = 0; i < workerCount; i++) {
        if (workerFreeAt[i] <= time) { freeIdx = i; break }
      }
      if (freeIdx === -1) break

      let chosen = null
      for (const name of remaining) {
        if (!isReady(name, time)) continue
        if (chosen === null) {
          chosen = name
          continue
        }
        const p = priority.get(name)
        const best = priority.get(chosen)
        if (p > best || (p === best && name < chosen)) chosen = name
      }
      if (chosen === null) break

      const cost = tasks.get(chosen)
      const finish = time + cost
      workerLog[freeIdx].push({ name: chosen, start: time, finish })
      workerFreeAt[freeIdx] = finish
      finishTime.set(chosen, finish)
      remaining.delete(chosen)
      startedSomething = true
    }

    if (remaining.size === 0) break

    let next = Infinity
    for (let i = 0; i < workerCount; i++) {
      if (workerFreeAt[i] > time && workerFreeAt[i] < next) next = workerFreeAt[i]
    }
    if (next === Infinity) break
    time = next
  }

  let makespan = 0
  for (const f of finishTime.values()) if (f > makespan) makespan = f

  return { workerLog, makespan }
}

export function formatPack({ workerLog, makespan }) {
  let out = ''
  workerLog.forEach((log, i) => {
    const parts = log.map((t) => ` ${t.name}@${t.start}-${t.finish}`).join('')
    out += `worker ${i}:${parts}\n`
  })
  out += `makespan ${makespan}\n`
  return out
}
"}

