{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e3-attempts-t5-20260919T123108Z/cell-BjKgnS/src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js waves`, `node src/cli.js explain` and
 * `node src/cli.js pack <workers>` each report on the build graph read from
 * standard input.
 */

import { readFileSync } from 'node:fs'
import { GraphError, parseGraph } from './graph.js'
import { findCycle } from './cycle.js'
import { computeSchedule, formatExplain, formatWaves } from './schedule.js'
import { formatPack, packWorkers } from './pack.js'

const WORKERS_RE = /^[1-9][0-9]*$/

function usageError() {
  process.stderr.write('error: usage: cli.js waves|explain|pack <workers>\n')
  process.exit(2)
}

function parseArgs(argv) {
  if (argv.length === 1 && (argv[0] === 'waves' || argv[0] === 'explain')) {
    return { mode: argv[0] }
  }
  if (argv.length === 2 && argv[0] === 'pack') {
    if (!WORKERS_RE.test(argv[1])) {
      process.stderr.write('error: workers must be a positive integer\n')
      process.exit(2)
    }
    return { mode: 'pack', workers: Number(argv[1]) }
  }
  usageError()
  return null
}

function main() {
  const args = parseArgs(process.argv.slice(2))

  const input = readFileSync(0, 'utf8')

  let graph
  try {
    graph = parseGraph(input)
  } catch (err) {
    if (err instanceof GraphError) {
      process.stderr.write(`error: ${err.message}\n`)
      process.exit(2)
    }
    throw err
  }

  const cycle = findCycle(graph)
  if (cycle) {
    process.stderr.write(`error: cycle: ${cycle.join(' -> ')}\n`)
    process.exit(3)
  }

  if (args.mode === 'waves') {
    process.stdout.write(formatWaves(computeSchedule(graph)))
  } else if (args.mode === 'explain') {
    process.stdout.write(formatExplain(computeSchedule(graph)))
  } else {
    process.stdout.write(formatPack(packWorkers(graph, args.workers)))
  }
}

main()
"}

