{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e3-attempts-t5-20260919T123108Z/cell-EGBBnN/src/diff.js","content":"/**
 * Line-based diff of a side against the base, using the longest common
 * subsequence with the tie-break rule from the task specification: a match
 * is taken whenever the current lines are equal, and otherwise the side
 * whose remaining subsequence is at least as long as the other's is
 * advanced, with the base preferred on a tie.
 */

/**
 * Build the LCS length table for `base` and `side`.
 *
 * `table[i][j]` holds the length of the longest common subsequence of
 * `base[i:]` and `side[j:]`.
 */
function buildLcsTable(base, side) {
  const m = base.length
  const n = side.length
  const table = new Array(m + 1)
  for (let i = 0; i <= m; i++) table[i] = new Uint32Array(n + 1)
  for (let i = m - 1; i >= 0; i--) {
    const row = table[i]
    const nextRow = table[i + 1]
    for (let j = n - 1; j >= 0; j--) {
      if (base[i] === side[j]) {
        row[j] = nextRow[j + 1] + 1
      } else {
        const advanceBase = nextRow[j]
        const advanceSide = row[j + 1]
        row[j] = advanceBase >= advanceSide ? advanceBase : advanceSide
      }
    }
  }
  return table
}

/**
 * Compute the changes turning `base` into `side`. Each change is a
 * contiguous run of base lines, described by `[baseStart, baseEnd)`,
 * replaced by a contiguous run of side lines described by
 * `[sideStart, sideEnd)`. An insertion has `baseStart === baseEnd`; a
 * deletion has `sideStart === sideEnd`.
 */
export function diffChanges(base, side) {
  const table = buildLcsTable(base, side)
  const m = base.length
  const n = side.length
  const changes = []
  let i = 0
  let j = 0
  let changeBaseStart = 0
  let changeSideStart = 0
  while (i < m || j < n) {
    if (i < m && j < n && base[i] === side[j]) {
      if (i > changeBaseStart || j > changeSideStart) {
        changes.push({ baseStart: changeBaseStart, baseEnd: i, sideStart: changeSideStart, sideEnd: j })
      }
      i++
      j++
      changeBaseStart = i
      changeSideStart = j
      continue
    }
    if (j >= n || (i < m && table[i + 1][j] >= table[i][j + 1])) {
      i++
    } else {
      j++
    }
  }
  if (i > changeBaseStart || j > changeSideStart) {
    changes.push({ baseStart: changeBaseStart, baseEnd: i, sideStart: changeSideStart, sideEnd: j })
  }
  return changes
}
"}

