{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e3-attempts-t5-20260919T123108Z/cell-EGBBnN/src/merge.js","content":"/**
 * Three-way merge of `mine` and `theirs` against their common `base`,
 * expressed as a sequence of regions. A region is either a stable stretch
 * of base lines, a stretch resolved to one side, a stretch where both sides
 * made the same change, or a conflict.
 */

import { diffChanges } from './diff.js'

function linesEqual(a, b) {
  if (a.length !== b.length) return false
  for (let i = 0; i < a.length; i++) if (a[i] !== b[i]) return false
  return true
}

/**
 * Reconstruct one side's lines over a region of the base, given only that
 * side's own changes. Base positions not covered by one of `changes` are
 * copied from `base` unchanged; positions covered by a change are replaced
 * by that change's side lines.
 */
function reconstructSide(base, side, changes, regionStart, regionEnd) {
  const lines = []
  let pos = regionStart
  for (const change of changes) {
    while (pos < change.baseStart) {
      lines.push(base[pos])
      pos++
    }
    for (let k = change.sideStart; k < change.sideEnd; k++) lines.push(side[k])
    pos = change.baseEnd
  }
  while (pos < regionEnd) {
    lines.push(base[pos])
    pos++
  }
  return lines
}

/**
 * Merge `mine`, `base` and `theirs` into an ordered list of regions.
 *
 * Each region is one of:
 * - `{ type: 'stable', lines }` — base lines neither side touched.
 * - `{ type: 'mine' | 'theirs' | 'both', lines }` — the resolved lines.
 * - `{ type: 'conflict', mine, base, theirs }` — the three candidate runs.
 */
export function buildRegions(mine, base, theirs) {
  const mineChanges = diffChanges(base, mine).map(c => ({ ...c, side: 'mine' }))
  const theirsChanges = diffChanges(base, theirs).map(c => ({ ...c, side: 'theirs' }))
  const allChanges = [...mineChanges, ...theirsChanges].sort((a, b) => {
    if (a.baseStart !== b.baseStart) return a.baseStart - b.baseStart
    if (a.side === b.side) return 0
    return a.side === 'mine' ? -1 : 1
  })

  const regions = []
  let stablePos = 0
  let index = 0
  while (index < allChanges.length) {
    let regionStart = allChanges[index].baseStart
    let regionEnd = allChanges[index].baseEnd
    const touching = [allChanges[index]]
    index++
    while (index < allChanges.length && allChanges[index].baseStart <= regionEnd) {
      touching.push(allChanges[index])
      if (allChanges[index].baseEnd > regionEnd) regionEnd = allChanges[index].baseEnd
      index++
    }

    if (regionStart > stablePos) {
      regions.push({ type: 'stable', lines: base.slice(stablePos, regionStart) })
    }

    const mineOwn = touching.filter(c => c.side === 'mine')
    const theirsOwn = touching.filter(c => c.side === 'theirs')
    const mineLines = reconstructSide(base, mine, mineOwn, regionStart, regionEnd)
    const theirsLines = reconstructSide(base, theirs, theirsOwn, regionStart, regionEnd)
    const baseLines = base.slice(regionStart, regionEnd)

    if (linesEqual(mineLines, theirsLines)) {
      regions.push({ type: 'both', lines: mineLines })
    } else if (linesEqual(mineLines, baseLines)) {
      regions.push({ type: 'theirs', lines: theirsLines })
    } else if (linesEqual(theirsLines, baseLines)) {
      regions.push({ type: 'mine', lines: mineLines })
    } else {
      regions.push({ type: 'conflict', mine: mineLines, base: baseLines, theirs: theirsLines })
    }

    stablePos = regionEnd
  }

  if (stablePos < base.length) {
    regions.push({ type: 'stable', lines: base.slice(stablePos) })
  }

  return regions
}
"}

