 * Reads a sheet from raw text into a map from canonical address key to its
 * declared content, in the order lines were declared. Throws `SheetError`
 * for a malformed line.
 */

import { parseAddressToken } from './address.js'

export class SheetError extends Error {}

/**
 * Parses sheet text into a `Map` from canonical address key (e.g. `A1`) to
 * `{ content, addr }`, where `addr` is the parsed `{ col, row, key }`.
 */
export function parseSheet(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const cells = new Map()
  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const line = lines[i]
    let idx = 0
    while (idx < line.length && (line[idx] === ' ' || line[idx] === '\t')) idx++
    const stripped = line.slice(idx)
    if (stripped.length === 0) continue
    if (stripped[0] === '#') continue

    let j = 0
    while (j < stripped.length && stripped[j] !== ' ' && stripped[j] !== '\t') j++
    const rawAddr = stripped.slice(0, j)

    let k = j
    while (k < stripped.length && (stripped[k] === ' ' || stripped[k] === '\t')) k++
    const content = stripped.slice(k)

    const upperAddr = rawAddr.toUpperCase()
    const addr = parseAddressToken(upperAddr)
    if (!addr) {
      throw new SheetError(`line ${lineNo}: invalid cell address ${upperAddr}`)
    }
    if (cells.has(addr.key)) {
      throw new SheetError(`line ${lineNo}: cell ${addr.key} is declared twice`)
    }
    cells.set(addr.key, { content, addr })
  }
  return cells
}
"}

