 * Evaluates a compiled sheet's cells to values, resolving cell references
 * lazily and detecting reference cycles as they are found.
 */

import { parseAddressToken, colToLetters } from './address.js'
import { mkNum, mkBool, mkErr, coerceNumber, finiteOrDivErr, compareValues } from './values.js'

const COMPARISON_APPLY = {
  '=': (c) => c === 0,
  '<>': (c) => c !== 0,
  '<': (c) => c < 0,
  '<=': (c) => c <= 0,
  '>': (c) => c > 0,
  '>=': (c) => c >= 0,
}

/**
 * Builds an evaluator bound to a compiled sheet (address key -> `{ literal }`
 * or `{ ast }`, `ast` being `null` for an ungrammatical formula).
 */
export function createEvaluator(compiled) {
  const cache = new Map()
  const visiting = new Set()

  function evaluateCellByKey(key) {
    if (cache.has(key)) return cache.get(key)
    if (!compiled.has(key)) return mkNum(0)
    if (visiting.has(key)) return mkErr('#CYCLE!')
    visiting.add(key)
    const cell = compiled.get(key)
    const result = cell.ast !== undefined ? (cell.ast === null ? mkErr('#ERR!') : evaluate(cell.ast)) : cell.literal
    visiting.delete(key)
    cache.set(key, result)
    return result
  }

  function evalAddress(token) {
    const addr = parseAddressToken(token)
    if (!addr) return mkErr('#REF!')
    return evaluateCellByKey(addr.key)
  }

  function expandRangeValues(node) {
    const from = parseAddressToken(node.from)
    const to = parseAddressToken(node.to)
    if (!from || !to) return [mkErr('#REF!')]
    const minCol = Math.min(from.col, to.col)
    const maxCol = Math.max(from.col, to.col)
    const minRow = Math.min(from.row, to.row)
    const maxRow = Math.max(from.row, to.row)
    const values = []
    for (let col = minCol; col <= maxCol; col++) {
      const letters = colToLetters(col)
      for (let row = minRow; row <= maxRow; row++) {
        values.push(evaluateCellByKey(`${letters}${row}`))
      }
    }
    return values
  }

  function argValues(node) {
    return node.type === 'Range' ? expandRangeValues(node) : [evaluate(node)]
  }

  function firstError(values) {
    for (const v of values) if (v.kind === 'error') return v
    return null
  }

  function evalAggregate(fname, argNodes) {
    const values = []
    for (const a of argNodes) values.push(...argValues(a))
    const err = firstError(values)
    if (err) return err
    if (fname === 'COUNT') return mkNum(values.filter((v) => v.kind === 'number').length)
    const nums = []
    for (const v of values) {
      const n = coerceNumber(v)
      if (n === null) return mkErr('#VALUE!')
      nums.push(n)
    }
    if (fname === 'SUM') return finiteOrDivErr(nums.reduce((a, b) => a + b, 0))
    if (fname === 'AVG') return finiteOrDivErr(nums.reduce((a, b) => a + b, 0) / nums.length)
    if (fname === 'MIN') return finiteOrDivErr(Math.min(...nums))
    return finiteOrDivErr(Math.max(...nums))
  }

  function evalAbs(argNode) {
    const values = argValues(argNode)
    const err = firstError(values)
    if (err) return err
    if (values.length !== 1) return mkErr('#ERR!')
    const n = coerceNumber(values[0])
    if (n === null) return mkErr('#VALUE!')
    return finiteOrDivErr(Math.abs(n))
  }

  function evalIf(argNodes) {
    const condValues = argValues(argNodes[0])
    const condErr = firstError(condValues)
    if (condErr) return condErr
    if (condValues.length !== 1) return mkErr('#ERR!')
    const cond = condValues[0]
    let truthy
    if (cond.kind === 'bool') truthy = cond.value
    else if (cond.kind === 'number') truthy = cond.value !== 0
    else return mkErr('#VALUE!')
    const branchValues = argValues(argNodes[truthy ? 1 : 2])
    const branchErr = firstError(branchValues)
    if (branchErr) return branchErr
    if (branchValues.length !== 1) return mkErr('#ERR!')
    return branchValues[0]
  }

  function evaluateCall(node) {
    const fname = node.name.toUpperCase()
    if (['SUM', 'MIN', 'MAX', 'AVG', 'COUNT'].includes(fname)) return evalAggregate(fname, node.args)
    if (fname === 'ABS') {
      if (node.args.length !== 1) return mkErr('#ERR!')
      return evalAbs(node.args[0])
    }
    if (fname === 'IF') {
      if (node.args.length !== 3) return mkErr('#ERR!')
      return evalIf(node.args)
    }
    return mkErr('#NAME?')
  }

  function evaluateArithmetic(op, left, right) {
    if (left.kind === 'error') return left
    if (right.kind === 'error') return right
    const ln = coerceNumber(left)
    const rn = coerceNumber(right)
    if (ln === null || rn === null) return mkErr('#VALUE!')
    let result
    if (op === '+') result = ln + rn
    else if (op === '-') result = ln - rn
    else if (op === '*') result = ln * rn
    else if (op === '/') result = ln / rn
    else result = Math.pow(ln, rn)
    return finiteOrDivErr(result)
  }

  function evaluate(node) {
    switch (node.type) {
      case 'Num':
        return mkNum(node.value)
      case 'Bool':
        return mkBool(node.value)
      case 'Paren':
        return evaluate(node.inner)
      case 'Address':
        return evalAddress(node.token)
      case 'Range':
        return mkErr('#ERR!')
      case 'Call':
        return evaluateCall(node)
      case 'UnaryOp': {
        const operand = evaluate(node.operand)
        if (operand.kind === 'error') return operand
        const n = coerceNumber(operand)
        if (n === null) return mkErr('#VALUE!')
        return finiteOrDivErr(node.op === '-' ? -n : n)
      }
      case 'BinOp': {
        if (COMPARISON_APPLY[node.op]) {
          const left = evaluate(node.left)
          if (left.kind === 'error') return left
          const right = evaluate(node.right)
          if (right.kind === 'error') return right
          return mkBool(COMPARISON_APPLY[node.op](compareValues(left, right)))
        }
        const left = evaluate(node.left)
        const right = evaluate(node.right)
        return evaluateArithmetic(node.op, left, right)
      }
      default:
        return mkErr('#ERR!')
    }
  }

  return { evaluateCellByKey }
}
"}

