    const c = rest[i]
    if (c === ':') {
      scheme = rest.slice(0, i)
      rest = rest.slice(i + 1)
      break
    }
    if (c === '/' || c === '?' || c === '#') break
  }

  let authority
  if (rest.startsWith('//')) {
    let j = 2
    while (j < rest.length && rest[j] !== '/' && rest[j] !== '?' && rest[j] !== '#') j++
    authority = rest.slice(2, j)
    rest = rest.slice(j)
  }

  const hashIdx = rest.indexOf('#')
  const pathAndQuery = hashIdx === -1 ? rest : rest.slice(0, hashIdx)
  const fragment = hashIdx === -1 ? undefined : rest.slice(hashIdx + 1)

  const qIdx = pathAndQuery.indexOf('?')
  const path = qIdx === -1 ? pathAndQuery : pathAndQuery.slice(0, qIdx)
  const query = qIdx === -1 ? undefined : pathAndQuery.slice(qIdx + 1)

  return { scheme, authority, path, query, fragment }
}

