function parseAuthority(authority) {
  const atIdx = authority.lastIndexOf('@')
  const userinfo = atIdx === -1 ? undefined : authority.slice(0, atIdx)
  const remainder = atIdx === -1 ? authority : authority.slice(atIdx + 1)

  const bracketIdx = remainder.lastIndexOf(']')
  const colonIdx = remainder.indexOf(':', bracketIdx + 1)
  const host = colonIdx === -1 ? remainder : remainder.slice(0, colonIdx)
  const port = colonIdx === -1 ? undefined : remainder.slice(colonIdx + 1)

  return { userinfo, host, port }
}

