function normalizePercent(str, componentName) {
  let out = ''
  for (let i = 0; i < str.length; i++) {
    const c = str[i]
    if (c !== '%') {
      out += c
      continue
    }
    const hex = str.slice(i + 1, i + 3)
    if (!HEX_RE.test(hex)) {
      throw new UriError(`the ${componentName} has a truncated percent-encoding`)
    }
    const code = parseInt(hex, 16)
    out += isUnreservedCharCode(code) ? String.fromCharCode(code) : '%' + hex.toUpperCase()
    i += 2
  }
  return out
}

