      input = input.slice(3)
    } else if (input.startsWith('./')) {
      input = input.slice(2)
    } else if (input.startsWith('/./')) {
      input = '/' + input.slice(3)
    } else if (input === '/.') {
      input = '/'
    } else if (input.startsWith('/../')) {
      input = '/' + input.slice(4)
      output = output.replace(/\/?[^/]*$/, '')
    } else if (input === '/..') {
      input = '/'
      output = output.replace(/\/?[^/]*$/, '')
    } else if (input === '.' || input === '..') {
      input = ''
    } else {
