  const pathNorm = normalizePercent(ref.path, 'path')
  const userinfoNorm = userinfo !== undefined ? normalizePercent(userinfo, 'userinfo') : undefined
  const hostNorm = host !== undefined ? normalizePercent(host, 'host') : undefined
  const queryNorm = ref.query !== undefined ? normalizePercent(ref.query, 'query') : undefined
  const fragmentNorm = ref.fragment !== undefined ? normalizePercent(ref.fragment, 'fragment') : undefined

