  if (portFinal !== undefined) {
    const defaultPort = schemeNorm !== undefined ? DEFAULT_PORTS[schemeNorm] : undefined
    if (portFinal === '' || portFinal === defaultPort) portFinal = undefined
  }

  let pathFinal = removeDotSegments(pathNorm)
  if (ref.authority !== undefined && pathFinal === '') pathFinal = '/'

  let out = ''
  if (schemeNorm !== undefined) out += schemeNorm + ':'
  if (ref.authority !== undefined) {
    let authorityStr = ''
    if (userinfoNorm !== undefined) authorityStr += userinfoNorm + '@'
    authorityStr += hostFinal
    if (portFinal !== undefined) authorityStr += ':' + portFinal
