/**
 * The command. `node src/cli.js normalize` normalizes one URI reference per
 * input line; `node src/cli.js resolve` resolves the reference on each line
 * against the base that precedes it. Both print one result per line.
 */

import fs from 'node:fs'
import { UriError, normalizeReference, resolveReference } from './uri.js'

function splitRecords(input) {
  if (input === '') return []
  const parts = input.split('\n')
  if (input.endsWith('\n')) parts.pop()
  return parts
}

function main(argv) {
  const mode = argv[0]
  if (argv.length !== 1 || (mode !== 'normalize' && mode !== 'resolve')) {
    process.stderr.write('error: usage: cli.js normalize|resolve\n')
    process.exit(2)
  }

  const input = fs.readFileSync(0, 'utf8')
  const records = splitRecords(input)
  const results = []

  for (let i = 0; i < records.length; i++) {
    const lineNo = i + 1
    const record = records[i]
    try {
      if (mode === 'normalize') {
        results.push(normalizeReference(record))
      } else {
        const spaceIdx = record.indexOf(' ')
        if (spaceIdx === -1) throw new UriError('expected a base and a reference')
        const base = record.slice(0, spaceIdx)
        const ref = record.slice(spaceIdx + 1)
        results.push(resolveReference(base, ref))
      }
    } catch (err) {
      if (err instanceof UriError) {
        process.stderr.write(`error: line ${lineNo}: ${err.message}\n`)
        process.exit(2)
      }
      throw err
    }
  }

  if (results.length > 0) process.stdout.write(results.map((line) => line + '\n').join(''))
  process.exit(0)
}

main(process.argv.slice(2))
"}

