{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e3-attempts-t5-20260919T123108Z/cell-JYuObN/src/policies.js","content":"/**
 * The two policy kinds a route can chain: token buckets and sliding windows.
 * Each keeps one independent state per key, created lazily the first time
 * that key reaches the policy.
 */

/**
 * A token bucket. Tokens are tracked as an integer count of `1/per`ths of a
 * token, so refilling by `refill` tokens per `per` ticks over any number of
 * elapsed ticks is exact integer arithmetic with no rounding.
 */
export class TokenBucket {
  constructor(capacity, refill, per) {
    this.capacity = capacity
    this.refill = refill
    this.per = per
    this.max = capacity * per
    this.states = new Map()
  }

  #state(key, tick) {
    let state = this.states.get(key)
    if (!state) {
      state = { units: this.max, lastTick: tick }
      this.states.set(key, state)
    }
    return state
  }

  advance(tick, key) {
    const state = this.#state(key, tick)
    const elapsed = tick - state.lastTick
    if (elapsed > 0n) {
      state.units += this.refill * elapsed
      if (state.units > this.max) state.units = this.max
      state.lastTick = tick
    }
  }

  allow(key) {
    return this.states.get(key).units >= this.per
  }

  record(key) {
    this.states.get(key).units -= this.per
  }
}

/**
 * A sliding window. Remembers the ticks of the requests it recorded for a
 * key and forgets any at or before `tick - span` on each advance.
 */
export class SlidingWindow {
  constructor(limit, span) {
    this.limit = limit
    this.span = span
    this.states = new Map()
  }

  #state(key) {
    let state = this.states.get(key)
    if (!state) {
      state = { ticks: [] }
      this.states.set(key, state)
    }
    return state
  }

  advance(tick, key) {
    const state = this.#state(key)
    const threshold = tick - this.span
    let cut = 0
    while (cut < state.ticks.length && state.ticks[cut] <= threshold) cut++
    if (cut > 0) state.ticks.splice(0, cut)
  }

  allow(key) {
    return BigInt(this.states.get(key).ticks.length) < this.limit
  }

  record(key, tick) {
    this.states.get(key).ticks.push(tick)
  }
}
"}

