 * The scanner for the small language described in the task. `scan(text)`
 * returns the list of tokens found in `text`, or throws a `LexError` at the
 * first point the input does not conform to the grammar.
 */

const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])

const PUNCTUATORS = [
  '==', '!=', '<=', '>=', '&&', '||', '->', '=>',
  '+', '-', '*', '/', '%', '=', '<', '>', '!',
  '(', ')', '{', '}', '[', ']', ',', ';', '.',
]

export class LexError extends Error {
  constructor(line, column, reason) {
    super(`${line}:${column}: ${reason}`)
    this.line = line
    this.column = column
    this.reason = reason
  }
}

function isLetter(c) {
  return c !== undefined && /[A-Za-z]/.test(c)
}

function isIdentStart(c) {
  return c !== undefined && (isLetter(c) || c === '_')
}

function isIdentPart(c) {
  return c !== undefined && (isLetter(c) || c === '_' || /[0-9]/.test(c))
}

function isDecimalDigit(c) {
  return c !== undefined && /[0-9]/.test(c)
}

function isHexDigit(c) {
  return c !== undefined && /[0-9a-fA-F]/.test(c)
}

function isOctalDigit(c) {
  return c !== undefined && /[0-7]/.test(c)
}

function isBinaryDigit(c) {
  return c === '0' || c === '1'
}

class Scanner {
  constructor(text) {
    this.chars = Array.from(text)
    this.i = 0
    this.line = 1
    this.column = 1
  }

  peek(offset = 0) {
    return this.chars[this.i + offset]
  }

  atEnd() {
    return this.i >= this.chars.length
  }

  pos() {
    return { line: this.line, column: this.column }
  }

  fail(pos, reason) {
    throw new LexError(pos.line, pos.column, reason)
  }

  // Consumes and returns the current character, advancing line/column.
  advance() {
    const c = this.chars[this.i]
    this.i += 1
    if (c === '\n') {
      this.line += 1
      this.column = 1
    } else if (c === '\t') {
      this.column = Math.floor((this.column - 1) / 4) * 4 + 5
    } else {
      this.column += 1
    }
    return c
  }

  skipWhitespaceAndComments() {
    for (;;) {
      const c = this.peek()
      if (c === ' ' || c === '\t' || c === '\r' || c === '\n') {
        this.advance()
        continue
      }
      if (c === '/' && this.peek(1) === '/') {
        this.advance()
        this.advance()
        while (!this.atEnd() && this.peek() !== '\n') this.advance()
        continue
      }
      if (c === '/' && this.peek(1) === '*') {
        const start = this.pos()
        this.advance()
        this.advance()
        let depth = 1
        while (depth > 0) {
          if (this.atEnd()) this.fail(start, 'unterminated block comment')
          if (this.peek() === '/' && this.peek(1) === '*') {
            this.advance()
            this.advance()
            depth += 1
          } else if (this.peek() === '*' && this.peek(1) === '/') {
            this.advance()
            this.advance()
            depth -= 1
          } else {
            this.advance()
          }
        }
        continue
      }
      break
    }
  }

  // Reads a run of digits (matching `isDigit`) allowing a single `_` between
  // two digits of the same run. Returns the text read (possibly empty).
  readDigitRun(isDigit) {
    let text = ''
    let lastWasDigit = false
    for (;;) {
      const c = this.peek()
      if (isDigit(c)) {
        text += this.advance()
        lastWasDigit = true
      } else if (c === '_' && lastWasDigit && isDigit(this.peek(1))) {
        text += this.advance()
        lastWasDigit = false
      } else {
        break
      }
    }
    return text
  }

  scanNumber() {
    const start = this.pos()
    let text = this.advance() // the digit that started the token

    let prefixNoDigit = false

    if (text === '0' && (this.peek() === 'x' || this.peek() === 'X')) {
      text += this.advance()
      const digits = this.readDigitRun(isHexDigit)
      text += digits
      prefixNoDigit = digits === ''
    } else if (text === '0' && (this.peek() === 'b' || this.peek() === 'B')) {
      text += this.advance()
      const digits = this.readDigitRun(isBinaryDigit)
      text += digits
      prefixNoDigit = digits === ''
    } else if (text === '0' && (this.peek() === 'o' || this.peek() === 'O')) {
      text += this.advance()
      const digits = this.readDigitRun(isOctalDigit)
      text += digits
      prefixNoDigit = digits === ''
    } else {
      text += this.readDigitRun(isDecimalDigit)

      if (this.peek() === '.' && isDecimalDigit(this.peek(1))) {
        text += this.advance()
        text += this.readDigitRun(isDecimalDigit)
      }

      if (this.peek() === 'e' || this.peek() === 'E') {
        const afterSignIsDigit = (this.peek(1) === '+' || this.peek(1) === '-') && isDecimalDigit(this.peek(2))
        if (isDecimalDigit(this.peek(1)) || afterSignIsDigit) {
          text += this.advance()
          if (this.peek() === '+' || this.peek() === '-') text += this.advance()
          text += this.readDigitRun(isDecimalDigit)
        }
      }
    }

    let trailing = ''
    while (isIdentPart(this.peek())) trailing += this.advance()
    text += trailing

    if (prefixNoDigit || trailing !== '') {
      this.fail(start, `invalid number ${text}`)
    }

    return { kind: 'number', line: start.line, column: start.column, text }
  }

  scanIdent() {
    const start = this.pos()
    let text = ''
    while (isIdentPart(this.peek())) text += this.advance()
    const kind = KEYWORDS.has(text) ? 'keyword' : 'ident'
    return { kind, line: start.line, column: start.column, text }
  }

  readHexDigits(count) {
    let text = ''
    for (let n = 0; n < count; n += 1) {
      if (!isHexDigit(this.peek())) return null
      text += this.advance()
    }
    return text
  }

  scanEscape(backslashPos) {
    if (this.atEnd()) return null // unterminated string, handled by caller
    const c = this.peek()
    if (c === 'n') { this.advance(); return '\n' }
    if (c === 't') { this.advance(); return '\t' }
    if (c === 'r') { this.advance(); return '\r' }
    if (c === '\\') { this.advance(); return '\\' }
    if (c === '"') { this.advance(); return '"' }
    if (c === '0') { this.advance(); return '\0' }
    if (c === 'x') {
      this.advance()
      const hex = this.readHexDigits(2)
      if (hex === null) this.fail(backslashPos, 'invalid escape \\x')
      return String.fromCharCode(parseInt(hex, 16))
    }
    if (c === 'u') {
      this.advance()
      if (this.peek() !== '{') this.fail(backslashPos, 'invalid escape \\u')
      this.advance()
      let hex = ''
      while (isHexDigit(this.peek())) hex += this.advance()
      if (hex === '' || this.peek() !== '}') this.fail(backslashPos, 'invalid escape \\u')
      this.advance()
      const codePoint = parseInt(hex, 16)
      if (codePoint > 0x10ffff) this.fail(backslashPos, 'invalid escape \\u')
      return String.fromCodePoint(codePoint)
    }
    this.fail(backslashPos, `invalid escape \\${c}`)
    return undefined
