{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e3-attempts-t5-20260919T123108Z/cell-PqdQbv/src/parse.js","content":"/**
 * Parses the line-oriented election format described in the task: a single
 * `candidates` declaration followed by any number of `ballot` records.
 */

const NAME_RE = /^[A-Za-z0-9_-]+$/

export class ParseError extends Error {
  constructor(message) {
    super(message)
    this.name = 'ParseError'
  }
}

/**
 * Parses the full election text and returns `{ candidates, ballots }`, where
 * `candidates` is the declared names in order and `ballots` is a list of
 * `{ count, names }` records. Throws {@link ParseError} on the first invalid
 * line, matching the task's stop-at-first-failure rule.
 */
export function parseElection(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  let candidates = null
  const known = new Set()
  const ballots = []

  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const line = lines[i].trim()
    if (line === '' || line.startsWith('#')) continue

    const tokens = line.split(/\s+/)
    const word = tokens[0]

    if (word === 'candidates') {
      if (candidates !== null || ballots.length > 0) {
        throw new ParseError(`line ${lineNo}: candidates must be declared once, before any ballot`)
      }
      const names = tokens.slice(1)
      if (names.length === 0) {
        throw new ParseError(`line ${lineNo}: expected candidates <name>...`)
      }
      const declared = new Set()
      for (const name of names) {
        if (!NAME_RE.test(name)) {
          throw new ParseError(`line ${lineNo}: invalid candidate name ${name}`)
        }
        if (declared.has(name)) {
          throw new ParseError(`line ${lineNo}: candidate ${name} is declared twice`)
        }
        declared.add(name)
      }
      candidates = names.slice()
      for (const name of names) known.add(name)
    } else if (word === 'ballot') {
      if (candidates === null) {
        throw new ParseError(`line ${lineNo}: candidates must be declared once, before any ballot`)
      }
      if (tokens.length < 3) {
        throw new ParseError(`line ${lineNo}: expected ballot <count> <candidate>...`)
      }
      const countStr = tokens[1]
      const names = tokens.slice(2)
      if (!/^[1-9][0-9]*$/.test(countStr)) {
        throw new ParseError(`line ${lineNo}: count must be a positive integer`)
      }
      const count = BigInt(countStr)
      const seen = new Set()
      for (const name of names) {
        if (!known.has(name)) {
          throw new ParseError(`line ${lineNo}: unknown candidate ${name}`)
        }
        if (seen.has(name)) {
          throw new ParseError(`line ${lineNo}: candidate ${name} is repeated`)
        }
        seen.add(name)
      }
      ballots.push({ count, names })
    } else {
      throw new ParseError(`line ${lineNo}: unknown directive ${word}`)
    }
  }

  if (candidates === null) {
    throw new ParseError('no candidates')
  }

  return { candidates, ballots }
}
"}

