 * Renders the round-by-round or summary output described in the task, given
 * the result of {@link module:election.runElection}.
 */

/**
 * Formats the full `rounds` output: one `round K: ...` line per round, with
 * an `eliminated <name>` line after rounds that removed a candidate, ending
 * with the `winner <name>` or `no winner` line.
 */
export function formatRounds(result) {
  const lines = []
  result.rounds.forEach((round, i) => {
    lines.push(formatRoundLine(i + 1, round))
    if (round.eliminated !== null) lines.push(`eliminated ${round.eliminated}`)
  })
  lines.push(result.winner !== null ? `winner ${result.winner}` : 'no winner')
  return lines.map((line) => line + '\n').join('')
}

/**
 * Formats the `tally` output: the number of rounds counted followed by the
 * `winner <name>` or `no winner` line.
 */
