 * The two policy kinds a route can enforce: a token bucket and a sliding
 * window. Both keep one independent state per key, created the first time
 * that key reaches the policy.
 */

export class TokenBucket {
  constructor(capacity, refill, per) {
    this.capacity = capacity
    this.refill = refill
    this.per = per
    this.states = new Map()
  }

  #state(key) {
    let state = this.states.get(key)
    if (!state) {
      state = { tokensNum: this.capacity * this.per, lastTick: null }
      this.states.set(key, state)
    }
    return state
  }

  advance(key, tick) {
    const state = this.#state(key)
    if (state.lastTick === null) {
      state.lastTick = tick
      return
    }
    if (tick > state.lastTick) {
      const elapsed = tick - state.lastTick
      const grown = state.tokensNum + this.refill * elapsed
      const cap = this.capacity * this.per
      state.tokensNum = grown > cap ? cap : grown
      state.lastTick = tick
    }
  }

  canAllow(key) {
    return this.#state(key).tokensNum >= this.per
  }

  record(key) {
    this.#state(key).tokensNum -= this.per
  }
}

export class SlidingWindow {
  constructor(limit, span) {
    this.limit = limit
    this.span = span
    this.states = new Map()
  }

  #state(key) {
    let state = this.states.get(key)
    if (!state) {
      state = { ticks: [] }
      this.states.set(key, state)
    }
    return state
  }

  advance(key, tick) {
    const state = this.#state(key)
    const threshold = tick - this.span
    state.ticks = state.ticks.filter((t) => t > threshold)
  }

  canAllow(key) {
    return BigInt(this.#state(key).ticks.length) < this.limit
  }

  record(key, tick) {
    this.#state(key).ticks.push(tick)
  }
}
"}

