{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js values` prints the value of every cell in the
 * sheet read from standard input, and `node src/cli.js deps` prints the cells
 * each one reads.
 */

import { parseSheet, SheetError } from './sheet.js'
import { Evaluator } from './evaluate.js'
import { collectDeps } from './deps.js'
import { formatValue } from './format.js'

function readStdin() {
  const chunks = []
  const fd = 0
  const buf = Buffer.alloc(65536)
  const fs = require('node:fs')
  let bytesRead
  do {
    try {
      bytesRead = fs.readSync(fd, buf, 0, buf.length, null)
    } catch (err) {
      if (err.code === 'EAGAIN') continue
      if (err.code === 'EOF') break
      throw err
    }
    if (bytesRead > 0) chunks.push(Buffer.from(buf.subarray(0, bytesRead)))
  } while (bytesRead > 0)
  return Buffer.concat(chunks).toString('utf8')
}

function sortedAddresses(cells) {
  return [...cells.entries()]
    .sort(([, a], [, b]) => (a.col !== b.col ? a.col - b.col : a.row - b.row))
    .map(([address]) => address)
}

function main() {
  const mode = process.argv[2]
  if (process.argv.length !== 3 || (mode !== 'values' && mode !== 'deps')) {
    process.stderr.write('error: usage: cli.js values|deps\n')
    process.exit(2)
  }

  const input = readStdin()
  let cells
  try {
    cells = parseSheet(input)
  } catch (err) {
    if (err instanceof SheetError) {
      process.stderr.write(`error: line ${err.line}: ${err.message}\n`)
      process.exit(2)
    }
    throw err
  }

  const addresses = sortedAddresses(cells)
  const lines = []

  if (mode === 'values') {
    const evaluator = new Evaluator(cells)
    for (const address of addresses) {
      const value = evaluator.evaluate(address)
      lines.push(`${address}=${formatValue(value)}`)
    }
  } else {
    const evaluator = new Evaluator(cells)
    for (const address of addresses) {
      const ast = evaluator.getAst(address)
      const deps = ast ? collectDeps(ast) : []
      lines.push(`${address}: ${deps.join(' ')}`.trimEnd())
    }
  }

  process.stdout.write(lines.length > 0 ? lines.join('\n') + '\n' : '')
}

main()
"}

