{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e3-attempts-t5-20260919T123108Z/cell-WMYi1O/src/parser.js","content":"/**
 * Recursive-descent parser for formula bodies.
 *
 * Precedence, loosest to tightest: comparisons, additive, multiplicative,
 * power (right-associative), leading sign (tighter than power, so `-2^2`
 * parses as `(-2)^2`). A range (`A1:B3`) parses as a primary anywhere the
 * grammar allows an expression; whether it is "directly a function
 * argument" is decided later, by the evaluator, from the AST shape.
 */

import { tokenize } from './tokenizer.js'
import { GrammarError } from './errors.js'

const COMPARISON_OPS = new Set(['=', '<>', '<', '<=', '>', '>='])
const ADDITIVE_OPS = new Set(['+', '-'])
const MULTIPLICATIVE_OPS = new Set(['*', '/'])

function splitWord(word) {
  const m = /^([A-Za-z]+)([0-9]*)$/.exec(word)
  return { letters: m[1], digits: m[2] }
}

class Parser {
  constructor(tokens) {
    this.tokens = tokens
    this.pos = 0
  }

  peek() {
    return this.tokens[this.pos]
  }

  next() {
    return this.tokens[this.pos++]
  }

  expectOp(ops) {
    const t = this.peek()
    return t && t.type === 'OP' && ops.has(t.op)
  }

  parse() {
    const node = this.parseComparison()
    if (this.pos !== this.tokens.length) throw new GrammarError()
    return node
  }

  parseComparison() {
    let left = this.parseAdditive()
    while (this.expectOp(COMPARISON_OPS)) {
      const op = this.next().op
      const right = this.parseAdditive()
      left = { type: 'bin', op, left, right }
    }
    return left
  }

  parseAdditive() {
    let left = this.parseMultiplicative()
    while (this.expectOp(ADDITIVE_OPS)) {
      const op = this.next().op
      const right = this.parseMultiplicative()
      left = { type: 'bin', op, left, right }
    }
    return left
  }

  parseMultiplicative() {
    let left = this.parsePower()
    while (this.expectOp(MULTIPLICATIVE_OPS)) {
      const op = this.next().op
      const right = this.parsePower()
      left = { type: 'bin', op, left, right }
    }
    return left
  }

  parsePower() {
    const left = this.parseUnary()
    if (this.expectOp(new Set(['^']))) {
      this.next()
      const right = this.parsePower()
      return { type: 'bin', op: '^', left, right }
    }
    return left
  }

  parseUnary() {
    if (this.expectOp(new Set(['+', '-']))) {
      const op = this.next().op
      const operand = this.parseUnary()
      return { type: 'un', op, operand }
    }
    return this.parsePrimary()
  }

  parsePrimary() {
    const t = this.peek()
    if (!t) throw new GrammarError()
    if (t.type === 'NUMBER') {
      this.next()
      return { type: 'num', value: Number(t.value) }
    }
    if (t.type === 'LPAREN') {
      this.next()
      const inner = this.parseComparison()
      if (!this.peek() || this.peek().type !== 'RPAREN') throw new GrammarError()
      this.next()
      return { type: 'paren', inner }
    }
    if (t.type === 'WORD') {
      this.next()
      const upper = t.value.toUpperCase()
      if (upper === 'TRUE') return { type: 'bool', value: true }
      if (upper === 'FALSE') return { type: 'bool', value: false }
      const next = this.peek()
      if (next && next.type === 'LPAREN') return this.parseCall(t.value)
      if (next && next.type === 'COLON') {
        this.next()
        const w2 = this.peek()
        if (!w2 || w2.type !== 'WORD') throw new GrammarError()
        this.next()
        return { type: 'range', a: splitWord(t.value), b: splitWord(w2.value) }
      }
      return { type: 'addr', ...splitWord(t.value) }
    }
    throw new GrammarError()
  }

  parseCall(name) {
    this.next() // consume LPAREN
    const args = []
    if (this.peek() && this.peek().type === 'RPAREN') throw new GrammarError()
    args.push(this.parseComparison())
    while (this.peek() && this.peek().type === 'COMMA') {
      this.next()
      args.push(this.parseComparison())
    }
    if (!this.peek() || this.peek().type !== 'RPAREN') throw new GrammarError()
    this.next()
    return { type: 'call', name, args }
  }
}

/** Parses a formula body (without the leading `=`) into an AST. */
export function parseFormula(body) {
  const tokens = tokenize(body)
  return new Parser(tokens).parse()
}
"}

