{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e3-attempts-t5-20260919T123108Z/cell-WMYi1O/src/evaluate.js","content":"/**
 * Evaluates cell values.
 *
 * Cycle detection falls out of ordinary recursive evaluation: a "visiting"
 * set tracks the cells currently on the call stack, and looking up a cell
 * that is already visiting yields `#CYCLE!` for that lookup. Because
 * `#CYCLE!` is just another error value, it propagates through operators
 * and functions the same way any other error does.
 */

import { classifyAddress, colLetters } from './address.js'

const COMPARISON_OPS = new Set(['=', '<>', '<', '<=', '>', '>='])

const NUM = (value) => ({ type: 'number', value })
const BOOL = (value) => ({ type: 'boolean', value })
const ERR = (value) => ({ type: 'error', value })

function toNumber(v) {
  if (v.type === 'number') return v
  if (v.type === 'boolean') return NUM(v.value ? 1 : 0)
  if (v.type === 'error') return v
  return ERR('#VALUE!')
}

function finite(n) {
  return Number.isFinite(n) ? NUM(n) : ERR('#DIV/0!')
}

function rank(v) {
  if (v.type === 'number') return 0
  if (v.type === 'text') return 1
  return 2 // boolean
}

function compareValues(l, r) {
  const rl = rank(l)
  const rr = rank(r)
  if (rl !== rr) return rl < rr ? -1 : 1
  if (l.type === 'number') return l.value < r.value ? -1 : l.value > r.value ? 1 : 0
  if (l.type === 'text') return l.value < r.value ? -1 : l.value > r.value ? 1 : 0
  const lv = l.value ? 1 : 0
  const rv = r.value ? 1 : 0
  return lv < rv ? -1 : lv > rv ? 1 : 0
}

/**
 * Reads a list of values as numbers, left to right; the first error (raw
 * or produced by a text-to-number conversion) wins.
 */
function toNumbersOrError(values) {
  const numbers = []
  for (const v of values) {
    if (v.type === 'error') return { error: v }
    const n = toNumber(v)
    if (n.type === 'error') return { error: n }
    numbers.push(n.value)
  }
  return { numbers }
}

function firstErrorOrFirst(values) {
  const err = values.find((v) => v.type === 'error')
  if (err) return err
  return values[0] ?? ERR('#REF!')
}

const CALL_SPECS = {
  SUM: { checkArgs: (n) => n >= 1 },
  MIN: { checkArgs: (n) => n >= 1 },
  MAX: { checkArgs: (n) => n >= 1 },
  COUNT: { checkArgs: (n) => n >= 1 },
  AVG: { checkArgs: (n) => n >= 1 },
  ABS: { checkArgs: (n) => n === 1 },
  IF: { checkArgs: (n) => n === 3 },
}

export function createEvaluator(model) {
  const cache = new Map()
  const visiting = new Set()

  function getCellValue(canonical) {
    if (cache.has(canonical)) return cache.get(canonical)
    if (visiting.has(canonical)) return ERR('#CYCLE!')
    const rec = model.get(canonical)
    if (!rec) {
      const v = NUM(0)
      cache.set(canonical, v)
      return v
    }
    visiting.add(canonical)
    let v
    if (rec.kind === 'literal') {
      v = rec.value
    } else if (!rec.ast) {
      v = ERR('#ERR!')
    } else {
      v = evalNode(rec.ast)
    }
    visiting.delete(canonical)
    cache.set(canonical, v)
    return v
  }

  function flattenRange(node) {
    const ca = classifyAddress(node.a.letters, node.a.digits)
    const cb = classifyAddress(node.b.letters, node.b.digits)
    if (!ca.valid || !cb.valid) return [ERR('#REF!')]
    const minCol = Math.min(ca.col, cb.col)
    const maxCol = Math.max(ca.col, cb.col)
    const minRow = Math.min(ca.row, cb.row)
    const maxRow = Math.max(ca.row, cb.row)
    const out = []
    for (let c = minCol; c <= maxCol; c++) {
      for (let r = minRow; r <= maxRow; r++) out.push(getCellValue(colLetters(c) + r))
    }
    return out
  }

  function flattenArg(node) {
    if (node.type === 'range') return flattenRange(node)
    return [evalNode(node)]
  }

  function evalNode(node) {
    switch (node.type) {
      case 'num':
        return NUM(node.value)
      case 'bool':
        return BOOL(node.value)
      case 'paren':
        return evalNode(node.inner)
      case 'range':
        // A range not used directly as a function argument is a grammar
        // corner the language accepts syntactically but always errors on.
        return ERR('#ERR!')
      case 'addr': {
        const cls = classifyAddress(node.letters, node.digits)
        if (!cls.valid) return ERR('#REF!')
        return getCellValue(cls.canonical)
      }
      case 'un': {
        const v = evalNode(node.operand)
        if (v.type === 'error') return v
        const n = toNumber(v)
        if (n.type === 'error') return n
        return finite(node.op === '-' ? -n.value : n.value)
      }
      case 'bin':
        return evalBin(node)
      case 'call':
        return evalCall(node)
      default:
        throw new Error(`unknown node type ${node.type}`)
    }
  }

  function evalBin(node) {
    const l = evalNode(node.left)
    if (l.type === 'error') return l
    const r = evalNode(node.right)
    if (r.type === 'error') return r
    if (COMPARISON_OPS.has(node.op)) {
      const c = compareValues(l, r)
      switch (node.op) {
        case '=':
          return BOOL(c === 0)
        case '<>':
          return BOOL(c !== 0)
        case '<':
          return BOOL(c < 0)
        case '<=':
          return BOOL(c <= 0)
        case '>':
          return BOOL(c > 0)
        case '>=':
          return BOOL(c >= 0)
      }
    }
    const ln = toNumber(l)
    if (ln.type === 'error') return ln
    const rn = toNumber(r)
    if (rn.type === 'error') return rn
    switch (node.op) {
      case '+':
        return finite(ln.value + rn.value)
      case '-':
        return finite(ln.value - rn.value)
      case '*':
        return finite(ln.value * rn.value)
      case '/':
        return finite(ln.value / rn.value)
      case '^':
        return finite(Math.pow(ln.value, rn.value))
    }
    throw new Error(`unknown operator ${node.op}`)
  }

  function evalCall(node) {
    const name = node.name.toUpperCase()
    const spec = CALL_SPECS[name]
    if (!spec) return ERR('#NAME?')
    if (!spec.checkArgs(node.args.length)) return ERR('#ERR!')

    if (name === 'IF') {
      const cond = firstErrorOrFirst(flattenArg(node.args[0]))
      if (cond.type === 'error') return cond
      let truthy
      if (cond.type === 'boolean') truthy = cond.value
      else if (cond.type === 'number') truthy = cond.value !== 0
      else return ERR('#VALUE!')
      const branch = truthy ? node.args[1] : node.args[2]
      return firstErrorOrFirst(flattenArg(branch))
    }

    const values = node.args.flatMap(flattenArg)

    if (name === 'COUNT') {
      const err = values.find((v) => v.type === 'error')
      if (err) return err
      return NUM(values.filter((v) => v.type === 'number').length)
    }

    if (name === 'ABS') {
      const { error, numbers } = toNumbersOrError(values)
      if (error) return error
      return finite(Math.abs(numbers[0]))
    }

    const { error, numbers } = toNumbersOrError(values)
    if (error) return error
    switch (name) {
      case 'SUM':
        return finite(numbers.reduce((a, b) => a + b, 0))
      case 'MIN':
        return finite(Math.min(...numbers))
      case 'MAX':
        return finite(Math.max(...numbers))
      case 'AVG':
        return finite(numbers.reduce((a, b) => a + b, 0) / numbers.length)
    }
    throw new Error(`unhandled function ${name}`)
  }

  return { getCellValue }
}
"}

