 * Splits raw standard input into the three documents it holds: mine, the
 * base, and theirs, as described by the CLI's input format.
 */

/**
 * Splits `raw` on newlines, dropping the empty tail a trailing newline
 * leaves, then splits those lines into documents wherever a line is exactly
 * `%%%`. Throws if the result is not exactly three documents.
 */
export function parseInput(raw) {
  const lines = raw.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') {
    lines.pop()
  }

  const parts = [[]]
  for (const line of lines) {
    if (line === '%%%') {
      parts.push([])
    } else {
      parts[parts.length - 1].push(line)
    }
  }

  if (parts.length !== 3) {
    throw new Error('expected three parts separated by %%%')
  }

  const [mine, base, theirs] = parts
  return { mine, base, theirs }
}
"}

