{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e3-attempts-t5-20260919T123108Z/cell-YwRm4C/src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js merge`, `node src/cli.js merge2` and
 * `node src/cli.js regions` each read three documents from standard input and
 * report the three-way merge of the second into the first and the third.
 */

import fs from 'node:fs'
import { parseInput } from './parseInput.js'
import { computeChanges } from './align.js'
import { buildRegions, resolveRegion } from './regions.js'

const MODES = ['merge', 'merge2', 'regions']

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function readStdin() {
  try {
    return fs.readFileSync(0, 'utf8')
  } catch {
    return ''
  }
}

function main() {
  const args = process.argv.slice(2)
  const mode = args[0]
  if (args.length !== 1 || !MODES.includes(mode)) {
    fail('usage: cli.js merge|merge2|regions')
  }

  const raw = readStdin()
  let mine
  let base
  let theirs
  try {
    ;({ mine, base, theirs } = parseInput(raw))
  } catch {
    fail('expected three parts separated by %%%')
  }

  const mineChanges = computeChanges(base, mine)
  const theirsChanges = computeChanges(base, theirs)
  const regions = buildRegions(base, mineChanges, theirsChanges)

  const output = []
  let conflict = false

  for (const region of regions) {
    if (region.kind === 'stable') {
      const count = region.end - region.start
      if (mode === 'regions') {
        output.push(`stable ${count}`)
      } else {
        for (let i = region.start; i < region.end; i++) output.push(base[i])
      }
      continue
    }

    const resolved = resolveRegion(region)
    if (resolved.type === 'conflict') {
      conflict = true
      if (mode === 'regions') {
        output.push(`conflict mine=${region.mineLines.length} base=${region.baseLines.length} theirs=${region.theirsLines.length}`)
      } else {
        output.push('<<<<<<< mine', ...region.mineLines)
        if (mode === 'merge') {
          output.push('||||||| base', ...region.baseLines)
        }
        output.push('=======', ...region.theirsLines, '>>>>>>> theirs')
      }
    } else if (mode === 'regions') {
      output.push(`${resolved.type} ${resolved.lines.length}`)
    } else {
      output.push(...resolved.lines)
    }
  }

  if (output.length > 0) {
    process.stdout.write(`${output.join('\n')}\n`)
  }
  process.exitCode = conflict ? 1 : 0
}

main()
"}

