{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e3-attempts-t5-20260919T123108Z/cell-aWK4Xd/src/parser.js","content":"/**
 * Parsing of the election description read from standard input.
 */

const NAME_RE = /^[A-Za-z0-9_-]+$/
const COUNT_RE = /^[1-9][0-9]*$/

/** An error tied to a specific input line, or to the input as a whole when `line` is null. */
export class ParseError extends Error {
  constructor(message, line) {
    super(message)
    this.line = line
  }
}

/**
 * Parses the full standard input text into `{ candidates, ballots }`, where
 * `candidates` is the declared names in declaration order and `ballots` is a
 * list of `{ count, names }` in the order they appear. Throws `ParseError`
 * per the specification's messages.
 */
export function parseElection(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  let candidates = null
  const candidateSet = new Set()
  const ballots = []

  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const trimmed = lines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue

    const tokens = trimmed.split(/\s+/)
    const word = tokens[0]

    if (word === 'candidates') {
      if (candidates !== null) {
        throw new ParseError('candidates must be declared once, before any ballot', lineNo)
      }
      const names = tokens.slice(1)
      if (names.length === 0) {
        throw new ParseError('expected candidates <name>...', lineNo)
      }
      const seen = new Set()
      for (const name of names) {
        if (!NAME_RE.test(name)) {
          throw new ParseError(`invalid candidate name ${name}`, lineNo)
        }
        if (seen.has(name)) {
          throw new ParseError(`candidate ${name} is declared twice`, lineNo)
        }
        seen.add(name)
      }
      candidates = names
      for (const name of names) candidateSet.add(name)
    } else if (word === 'ballot') {
      if (candidates === null) {
        throw new ParseError('candidates must be declared once, before any ballot', lineNo)
      }
      const rest = tokens.slice(1)
      if (rest.length < 2) {
        throw new ParseError('expected ballot <count> <candidate>...', lineNo)
      }
      const [countStr, ...names] = rest
      if (!COUNT_RE.test(countStr)) {
        throw new ParseError('count must be a positive integer', lineNo)
      }
      const seen = new Set()
      for (const name of names) {
        if (!candidateSet.has(name)) {
          throw new ParseError(`unknown candidate ${name}`, lineNo)
        }
        if (seen.has(name)) {
          throw new ParseError(`candidate ${name} is repeated`, lineNo)
        }
        seen.add(name)
      }
      ballots.push({ count: Number(countStr), names })
    } else {
      throw new ParseError(`unknown directive ${word}`, lineNo)
    }
  }

  if (candidates === null) {
    throw new ParseError('no candidates', null)
  }

  return { candidates, ballots }
}
"}

