{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e3-attempts-t5-20260919T123108Z/cell-aWK4Xd/src/format.js","content":"/**
 * Rendering of a counted election as the `rounds` and `tally` output.
 */

/** Formats one round's tally line, without a trailing newline. */
function formatRound(index, tally, exhausted) {
  const entries = [...tally.entries()].sort((a, b) => {
    if (a[1] !== b[1]) return b[1] - a[1]
    return a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0
  })
  const parts = entries.map(([name, votes]) => `${name}=${votes}`)
  parts.push(`exhausted=${exhausted}`)
  return `round ${index + 1}: ${parts.join(' ')}`
}

/** Renders the full `rounds` output for a counted election. */
export function formatRounds({ rounds, winner }) {
  const lines = []
  rounds.forEach((round, index) => {
    lines.push(formatRound(index, round.tally, round.exhausted))
    if (round.eliminated !== null) lines.push(`eliminated ${round.eliminated}`)
  })
  lines.push(winner !== null ? `winner ${winner}` : 'no winner')
  return lines.map((line) => `${line}\n`).join('')
}

/** Renders the full `tally` output for a counted election. */
export function formatTally({ rounds, winner }) {
  const lines = [`rounds ${rounds.length}`, winner !== null ? `winner ${winner}` : 'no winner']
  return lines.map((line) => `${line}\n`).join('')
}
"}

