{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e3-attempts-t5-20260919T123108Z/cell-aWK4Xd/src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js rounds` prints every round of the instant-runoff
 * count read from standard input, and `node src/cli.js tally` prints only how
 * many rounds ran and who won.
 */

import { parseElection, ParseError } from './parser.js'
import { countElection } from './election.js'
import { formatRounds, formatTally } from './format.js'

function readStdin() {
  const chunks = []
  const fd = 0
  const buffer = Buffer.alloc(65536)
  const fs = require('node:fs')
  for (;;) {
    let bytesRead
    try {
      bytesRead = fs.readSync(fd, buffer, 0, buffer.length, null)
    } catch (err) {
      if (err.code === 'EAGAIN') continue
      if (err.code === 'EOF') break
      throw err
    }
    if (bytesRead === 0) break
    chunks.push(Buffer.from(buffer.subarray(0, bytesRead)))
  }
  return Buffer.concat(chunks).toString('utf8')
}

function main() {
  const mode = process.argv[2]
  if (process.argv.length !== 3 || (mode !== 'rounds' && mode !== 'tally')) {
    process.stderr.write('error: usage: cli.js rounds|tally\n')
    process.exit(2)
  }

  const input = readStdin()

  let election
  try {
    election = parseElection(input)
  } catch (err) {
    if (err instanceof ParseError) {
      const message = err.line === null ? `error: ${err.message}\n` : `error: line ${err.line}: ${err.message}\n`
      process.stderr.write(message)
      process.exit(2)
    }
    throw err
  }

  const counted = countElection(election.candidates, election.ballots)
  const output = mode === 'rounds' ? formatRounds(counted) : formatTally(counted)
  process.stdout.write(output)
  process.exit(0)
}

main()
"}

