{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e3-attempts-t5-20260919T123108Z/cell-af4gnl/src/merge.js","content":"/**
 * Three-way merge: split a base document into stable regions and regions
 * touched by one or both sides' changes, then resolve each touched region.
 */

import { computeChanges } from './diff.js'

function linesEqual(a, b) {
  if (a.length !== b.length) return false
  for (let i = 0; i < a.length; i++) if (a[i] !== b[i]) return false
  return true
}

/**
 * Split the base document into an ordered list of regions covering it end
 * to end, each either stable (untouched by either side) or touched by one
 * or more changes from either side.
 */
function buildRegionGroups(mineChanges, theirsChanges, baseLength) {
  const tagged = [
    ...mineChanges.map(c => ({ ...c, side: 'mine' })),
    ...theirsChanges.map(c => ({ ...c, side: 'theirs' })),
  ].sort((a, b) => {
    if (a.baseStart !== b.baseStart) return a.baseStart - b.baseStart
    if (a.side === b.side) return 0
    return a.side === 'mine' ? -1 : 1
  })

  const groups = []
  for (const change of tagged) {
    const last = groups[groups.length - 1]
    if (last && change.baseStart <= last.end) {
      last.end = Math.max(last.end, change.baseEnd)
      last.changes.push(change)
    } else {
      groups.push({ start: change.baseStart, end: change.baseEnd, changes: [change] })
    }
  }

  const regions = []
  let pos = 0
  for (const group of groups) {
    if (group.start > pos) regions.push({ type: 'stable', start: pos, end: group.start })
    regions.push({ type: 'changed', start: group.start, end: group.end, changes: group.changes })
    pos = group.end
  }
  if (pos < baseLength) regions.push({ type: 'stable', start: pos, end: baseLength })

  return regions
}

/**
 * Reconstruct one side's lines for a changed region: the side's own change
 * lines where it made a change, and the base's lines everywhere else in
 * the region.
 */
function reconstructSide(region, base, sideArray, sideName) {
  const sideChanges = region.changes
    .filter(c => c.side === sideName)
    .sort((a, b) => a.baseStart - b.baseStart)
  if (sideChanges.length === 0) return base.slice(region.start, region.end)

  const out = []
  let pos = region.start
  for (const change of sideChanges) {
    out.push(...base.slice(pos, change.baseStart))
    out.push(...sideArray.slice(change.sideStart, change.sideEnd))
    pos = change.baseEnd
  }
  out.push(...base.slice(pos, region.end))
  return out
}

/**
 * Resolve a changed region into one of: `both` (the sides made the same
 * change), `mine` or `theirs` (only that side changed it) or `conflict`.
 */
function resolveRegion(region, mine, base, theirs) {
  const mineLines = reconstructSide(region, base, mine, 'mine')
  const theirsLines = reconstructSide(region, base, theirs, 'theirs')
  const baseLines = base.slice(region.start, region.end)

  if (linesEqual(mineLines, theirsLines)) return { kind: 'both', lines: mineLines, mineLines, baseLines, theirsLines }
  if (linesEqual(mineLines, baseLines)) return { kind: 'theirs', lines: theirsLines, mineLines, baseLines, theirsLines }
  if (linesEqual(theirsLines, baseLines)) return { kind: 'mine', lines: mineLines, mineLines, baseLines, theirsLines }
  return { kind: 'conflict', mineLines, baseLines, theirsLines }
}

/**
 * Merge `mine` and `theirs` against their common `base`, returning an
 * ordered list of resolved regions.
 *
 * Each region is either `{ kind: 'stable' | 'both' | 'mine' | 'theirs',
 * lines }` or `{ kind: 'conflict', mineLines, baseLines, theirsLines }`.
 */
export function mergeDocuments(mine, base, theirs) {
  const mineChanges = computeChanges(base, mine)
  const theirsChanges = computeChanges(base, theirs)
  const regions = buildRegionGroups(mineChanges, theirsChanges, base.length)

  return regions.map(region => {
    if (region.type === 'stable') return { kind: 'stable', lines: base.slice(region.start, region.end) }
    return resolveRegion(region, mine, base, theirs)
  })
}
"}

