import { readFileSync } from 'node:fs'
import { mergeDocuments } from './merge.js'

const MODES = ['merge', 'merge2', 'regions']

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function splitInput(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const docs = [[]]
  for (const line of lines) {
    if (line === '%%%') docs.push([])
    else docs[docs.length - 1].push(line)
  }
  return docs
}

function renderConflict(region, includeBase) {
  const lines = ['<<<<<<< mine', ...region.mineLines]
  if (includeBase) lines.push('||||||| base', ...region.baseLines)
  lines.push('=======', ...region.theirsLines, '>>>>>>> theirs')
  return lines
}

function runMerge(regions, includeBase) {
  const output = []
  let hasConflict = false
  for (const region of regions) {
    if (region.kind === 'conflict') {
      hasConflict = true
      output.push(...renderConflict(region, includeBase))
    } else {
      output.push(...region.lines)
    }
  }
  return { output, hasConflict }
}

function runRegions(regions) {
  const output = []
  let hasConflict = false
  for (const region of regions) {
    if (region.kind === 'conflict') {
      hasConflict = true
      output.push(`conflict mine=${region.mineLines.length} base=${region.baseLines.length} theirs=${region.theirsLines.length}`)
    } else {
      output.push(`${region.kind} ${region.lines.length}`)
    }
  }
  return { output, hasConflict }
}

function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || !MODES.includes(args[0])) {
    fail('usage: cli.js merge|merge2|regions')
  }
  const mode = args[0]

  const input = readFileSync(0, 'utf8')
  const docs = splitInput(input)
  if (docs.length !== 3) fail('expected three parts separated by %%%')

  const [mine, base, theirs] = docs
  const regions = mergeDocuments(mine, base, theirs)

  let result
  if (mode === 'merge') result = runMerge(regions, true)
  else if (mode === 'merge2') result = runMerge(regions, false)
  else result = runRegions(regions)

  const text = result.output.length > 0 ? `${result.output.join('\n')}\n` : ''
  process.stdout.write(text)
  process.exit(result.hasConflict ? 1 : 0)
}

main()
"}

