{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e3-attempts-t5-20260919T123108Z/cell-ahamEJ/src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js rounds` prints every round of the instant-runoff
 * count read from standard input, and `node src/cli.js tally` prints only how
 * many rounds ran and who won.
 */

import { parseElection } from './parse.js'
import { countRounds } from './election.js'
import { ParseError } from './parse-error.js'

function readStdin() {
  const chunks = []
  const fd = 0
  const buffer = Buffer.alloc(65536)
  const fs = require('node:fs')
  for (;;) {
    let bytesRead
    try {
      bytesRead = fs.readSync(fd, buffer, 0, buffer.length, null)
    } catch (error) {
      if (error.code === 'EAGAIN') continue
      if (error.code === 'EOF') break
      throw error
    }
    if (bytesRead === 0) break
    chunks.push(Buffer.from(buffer.subarray(0, bytesRead)))
  }
  return Buffer.concat(chunks).toString('utf8')
}

function formatRoundLine(roundNumber, round) {
  const entries = [...round.votes.entries()]
  entries.sort((a, b) => (b[1] - a[1]) || (a[0] < b[0] ? -1 : 1))
  const parts = entries.map(([name, count]) => `${name}=${count}`)
  parts.push(`exhausted=${round.exhausted}`)
  return `round ${roundNumber}: ${parts.join(' ')}`
}

function main() {
  const args = process.argv.slice(2)
  const mode = args[0]
  if (args.length !== 1 || (mode !== 'rounds' && mode !== 'tally')) {
    process.stderr.write('error: usage: cli.js rounds|tally\n')
    process.exit(2)
  }

  const input = readStdin()

  let election
  try {
    election = parseElection(input)
  } catch (error) {
    if (error instanceof ParseError) {
      process.stderr.write(error.message + '\n')
      process.exit(2)
    }
    throw error
  }

  const rounds = countRounds(election)
  const lines = []

  if (mode === 'rounds') {
    for (let i = 0; i < rounds.length; i++) {
      lines.push(formatRoundLine(i + 1, rounds[i]))
      if (rounds[i].eliminated !== null) lines.push(`eliminated ${rounds[i].eliminated}`)
    }
  } else {
    lines.push(`rounds ${rounds.length}`)
  }

  const winner = rounds[rounds.length - 1].winner
  lines.push(winner === null ? 'no winner' : `winner ${winner}`)

  process.stdout.write(lines.join('\n') + '\n')
}

main()
"}

