 * Normalization of a parsed URI reference back into its shortest,
 * canonical string form.
 */

import { CliError } from './cli-error.js'
import { removeDotSegments, splitAuthority } from './uri-reference.js'

const DEFAULT_PORTS = { http: '80', https: '443', ws: '80', wss: '443', ftp: '21' }
const UNRESERVED = /^[A-Za-z0-9\-._~]$/

/**
 * Normalizes the components of a URI reference (as produced by
 * `parseUriReference` or `resolveReference`) and returns the printable
 * string. Throws a `CliError` naming `lineNumber` if a `%` in any of
 * userinfo, host, path, query or fragment is not followed by two
 * hexadecimal digits.
 */
export function normalizeComponents(components, lineNumber) {
  const scheme = components.schemePresent ? lowerAscii(components.scheme) : ''

  let userinfoPresent = false
  let userinfo = ''
  let host = ''
  let portPresent = false
  let port = ''
  if (components.authorityPresent) {
    ;({ userinfoPresent, userinfo, host, portPresent, port } = splitAuthority(components.authority))
  }

