 * RFC 3986 generic-syntax parsing, normalization and reference resolution.
 */

const DEFAULT_PORTS = {
  http: '80',
  ws: '80',
  https: '443',
  wss: '443',
  ftp: '21',
}

/** Thrown when a component carries a truncated percent-encoding. */
export class PercentEncodingError extends Error {
  constructor(component) {
    super(`the ${component} has a truncated percent-encoding`)
    this.component = component
  }
}

/**
 * Split a URI reference into its generic-syntax components. Absent
 * components are `null`; an authority that is present but empty is
 * represented by `authorityPresent: true` with an empty `host`.
 */
export function parse(s) {
  let scheme = null
  let rest = s
  let i = 0
  while (i < s.length && s[i] !== ':' && s[i] !== '/' && s[i] !== '?' && s[i] !== '#') i++
  if (i < s.length && s[i] === ':') {
    scheme = s.slice(0, i)
    rest = s.slice(i + 1)
  }

  let authorityPresent = false
  let userinfo = null
  let host = null
  let port = null
  if (rest.startsWith('//')) {
    authorityPresent = true
    let j = 2
    while (j < rest.length && rest[j] !== '/' && rest[j] !== '?' && rest[j] !== '#') j++
    const authority = rest.slice(2, j)
    rest = rest.slice(j)

    let a = authority
    const atIdx = a.lastIndexOf('@')
    if (atIdx !== -1) {
      userinfo = a.slice(0, atIdx)
      a = a.slice(atIdx + 1)
    }
    const bracketIdx = a.lastIndexOf(']')
    const colonIdx = a.indexOf(':', bracketIdx + 1)
    if (colonIdx !== -1) {
      host = a.slice(0, colonIdx)
      port = a.slice(colonIdx + 1)
    } else {
      host = a
    }
  }

  let k = 0
  while (k < rest.length && rest[k] !== '?' && rest[k] !== '#') k++
  const path = rest.slice(0, k)
  rest = rest.slice(k)

  let query = null
  if (rest[0] === '?') {
    let m = 1
    while (m < rest.length && rest[m] !== '#') m++
    query = rest.slice(1, m)
    rest = rest.slice(m)
  }

  let fragment = null
  if (rest[0] === '#') fragment = rest.slice(1)

  return { scheme, authorityPresent, userinfo, host, port, path, query, fragment }
}

const UNRESERVED = /[A-Za-z0-9\-._~]/

/**
 * Normalize percent-encodings in a single string: uppercase the hex
 * digits, and replace the triplet with the character it encodes when
 * that character is unreserved. Returns `null` when a `%` is not
 * followed by two hexadecimal digits.
 */
function normalizePercentString(str) {
  let out = ''
  for (let i = 0; i < str.length; i++) {
    const c = str[i]
    if (c === '%') {
      const digits = str.slice(i + 1, i + 3)
      if (!/^[0-9A-Fa-f]{2}$/.test(digits)) return null
      const upper = digits.toUpperCase()
      const ch = String.fromCharCode(parseInt(upper, 16))
      out += UNRESERVED.test(ch) ? ch : '%' + upper
      i += 2
    } else {
      out += c
    }
  }
  return out
}

/**
 * Check and normalize the percent-encodings of every component present
 * on a parsed URI reference, in the order path, userinfo, host, query,
 * fragment. Throws {@link PercentEncodingError} for the first invalid
 * one found. Returns a shallow copy with the normalized strings.
 */
export function normalizePercentEncodings(parsed) {
  const result = { ...parsed }
  const order = ['path', 'userinfo', 'host', 'query', 'fragment']
  for (const key of order) {
    const value = parsed[key]
    if (value === null || value === undefined) continue
    const normalized = normalizePercentString(value)
    if (normalized === null) throw new PercentEncodingError(key)
    result[key] = normalized
  }
  return result
}

function lowerAscii(s) {
  return s.replace(/[A-Z]/g, (c) => c.toLowerCase())
}

/** Remove `.` and `..` segments from a path per RFC 3986 section 5.2.4. */
export function removeDotSegments(path) {
  let input = path
  let output = ''
  while (input.length > 0) {
    if (input.startsWith('../')) {
      input = input.slice(3)
    } else if (input.startsWith('./')) {
      input = input.slice(2)
    } else if (input.startsWith('/./')) {
      input = '/' + input.slice(3)
    } else if (input === '/.') {
      input = '/'
    } else if (input.startsWith('/../')) {
      input = '/' + input.slice(4)
      output = removeLastSegment(output)
    } else if (input === '/..') {
      input = '/'
      output = removeLastSegment(output)
    } else if (input === '.' || input === '..') {
      input = ''
    } else {
      let start = 0
      if (input[0] === '/') start = 1
      let nextSlash = input.indexOf('/', start)
      if (nextSlash === -1) nextSlash = input.length
      output += input.slice(0, nextSlash)
      input = input.slice(nextSlash)
    }
  }
  return output
}

function removeLastSegment(output) {
  const idx = output.lastIndexOf('/')
  return idx === -1 ? '' : output.slice(0, idx)
}

/**
 * Normalize a parsed URI reference: lowercase the scheme, normalize
 * percent-encodings, lowercase the host, drop a default or empty port,
 * remove dot segments from the path, and default the path to `/` when
 * an authority is present and the path is empty.
 */
export function normalize(parsed) {
  const withScheme = { ...parsed, scheme: parsed.scheme === null ? null : lowerAscii(parsed.scheme) }
  const withPercent = normalizePercentEncodings(withScheme)

  const result = { ...withPercent }
  if (result.host !== null) result.host = lowerAscii(result.host)

  if (result.port !== null) {
    const scheme = result.scheme
    const defaultPort = scheme === null ? undefined : DEFAULT_PORTS[scheme]
    if (result.port === '' || result.port === defaultPort) result.port = null
  }

  result.path = removeDotSegments(result.path)
  if (result.authorityPresent && result.path === '') result.path = '/'

  return result
}

function mergePaths(base, refPath) {
  if (base.authorityPresent && base.path === '') return '/' + refPath
  const idx = base.path.lastIndexOf('/')
  if (idx === -1) return refPath
  return base.path.slice(0, idx + 1) + refPath
}

/**
 * Resolve a parsed reference against a parsed base per RFC 3986
 * section 5.2.2, strict mode. The result is not yet normalized.
 */
export function resolveReference(base, ref) {
  const target = {}
  if (ref.scheme !== null) {
    target.scheme = ref.scheme
    target.authorityPresent = ref.authorityPresent
    target.userinfo = ref.userinfo
    target.host = ref.host
    target.port = ref.port
    target.path = removeDotSegments(ref.path)
    target.query = ref.query
  } else {
    target.scheme = base.scheme
    if (ref.authorityPresent) {
      target.authorityPresent = true
      target.userinfo = ref.userinfo
      target.host = ref.host
      target.port = ref.port
      target.path = removeDotSegments(ref.path)
      target.query = ref.query
    } else {
      target.authorityPresent = base.authorityPresent
      target.userinfo = base.userinfo
      target.host = base.host
      target.port = base.port
      if (ref.path === '') {
        target.path = base.path
        target.query = ref.query !== null ? ref.query : base.query
      } else {
        const mergedPath = ref.path.startsWith('/') ? ref.path : mergePaths(base, ref.path)
        target.path = removeDotSegments(mergedPath)
        target.query = ref.query
      }
    }
  }
  target.fragment = ref.fragment
  return target
}
"}

