/**
 * The command. `node src/cli.js normalize` normalizes one URI reference per
 * input line; `node src/cli.js resolve` resolves the reference on each line
 * against the base that precedes it. Both print one result per line.
 */

import { parse, normalize, normalizePercentEncodings, resolveReference, serialize, PercentEncodingError } from './uri.js'

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function readStdin() {
  const chunks = []
  const fd = 0
  const buf = Buffer.alloc(65536)
  const fs = require('node:fs')
  while (true) {
    let bytesRead
    try {
      bytesRead = fs.readSync(fd, buf, 0, buf.length, null)
    } catch (err) {
      if (err.code === 'EAGAIN') continue
      if (err.code === 'EOF') break
      throw err
    }
    if (bytesRead === 0) break
    chunks.push(Buffer.from(buf.subarray(0, bytesRead)))
  }
  return Buffer.concat(chunks).toString('utf8')
}

function main() {
  const args = process.argv.slice(2)
  const mode = args[0]
  if (args.length !== 1 || (mode !== 'normalize' && mode !== 'resolve')) {
    fail('usage: cli.js normalize|resolve')
  }

  const input = readStdin()
  let lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const output = []
  for (let i = 0; i < lines.length; i++) {
    const lineNumber = i + 1
    const line = lines[i]
    try {
      if (mode === 'normalize') {
        output.push(serialize(normalize(parse(line))))
      } else {
        const spaceIdx = line.indexOf(' ')
        if (spaceIdx === -1) {
          throw new Error('expected a base and a reference')
        }
        const baseStr = line.slice(0, spaceIdx)
        const refStr = line.slice(spaceIdx + 1)
        const base = parse(baseStr)
        if (base.scheme === null) {
          throw new Error('the base has no scheme')
        }
        normalizePercentEncodings(base)
        const ref = parse(refStr)
        normalizePercentEncodings(ref)
        const target = resolveReference(base, ref)
        output.push(serialize(normalize(target)))
      }
    } catch (err) {
      if (err instanceof PercentEncodingError) {
        fail(`line ${lineNumber}: ${err.message}`)
      } else {
        fail(`line ${lineNumber}: ${err.message}`)
      }
    }
  }

  process.stdout.write(output.length > 0 ? output.join('\n') + '\n' : '')
  process.exit(0)
}

main()
"}

