    return value
  }

  function evalContent(content) {
    if (!content.startsWith('=')) return parseLiteral(content)
    const ast = getFormula(content)
    if (!ast) return err('#ERR!')
    return evalNode(ast)
  }

  function resolveAddr(word) {
    const info = parseAddress(word)
    if (!info) return err('#REF!')
    return getCellValue(addressKey(info.col, info.row))
  }

  function flattenRange(node) {
    const a = parseAddress(node.a)
    const b = parseAddress(node.b)
    if (!a || !b) return [err('#REF!')]
    const colLo = Math.min(a.col, b.col)
    const colHi = Math.max(a.col, b.col)
    const rowLo = Math.min(a.row, b.row)
    const rowHi = Math.max(a.row, b.row)
    const out = []
    for (let c = colLo; c <= colHi; c++) {
      for (let r = rowLo; r <= rowHi; r++) {
        out.push(getCellValue(addressKey(c, r)))
      }
    }
    return out
  }

  function flattenArg(node) {
    if (node.type === 'range') return flattenRange(node)
    return [evalNode(node)]
  }

  function evalSingle(node) {
    const list = flattenArg(node)
    for (const v of list) if (v.t === 'err') return v
    if (list.length !== 1) return err('#VALUE!')
    return list[0]
  }

  function toBool(v) {
    if (v.t === 'err') return v
    if (v.t === 'bool') return v
    if (v.t === 'num') return bool(v.v !== 0)
    return err('#VALUE!')
  }

  function evalCall(name, args) {
    if (name === 'SUM' || name === 'MIN' || name === 'MAX' || name === 'COUNT' || name === 'AVG') {
      if (args.length < 1) return err('#ERR!')
      const list = []
      for (const a of args) list.push(...flattenArg(a))
      for (const v of list) if (v.t === 'err') return v
      if (name === 'COUNT') return num(list.filter((v) => v.t === 'num').length)
      const nums = []
      for (const v of list) {
        const n = toNumber(v)
        if (n.t === 'err') return n
        nums.push(n.v)
      }
      if (name === 'SUM') return finalizeNumber(nums.reduce((a, b) => a + b, 0))
      if (name === 'MIN') return finalizeNumber(Math.min(...nums))
      if (name === 'MAX') return finalizeNumber(Math.max(...nums))
      return finalizeNumber(nums.reduce((a, b) => a + b, 0) / nums.length)
    }
    if (name === 'ABS') {
      if (args.length !== 1) return err('#ERR!')
      const v = evalSingle(args[0])
      if (v.t === 'err') return v
      const n = toNumber(v)
      if (n.t === 'err') return n
      return finalizeNumber(Math.abs(n.v))
    }
    if (name === 'IF') {
      if (args.length !== 3) return err('#ERR!')
      const cond = evalSingle(args[0])
      if (cond.t === 'err') return cond
      const b = toBool(cond)
      if (b.t === 'err') return b
      return evalSingle(b.v ? args[1] : args[2])
    }
    return err('#NAME?')
  }

  function evalNode(node) {
    switch (node.type) {
      case 'num': return num(node.value)
      case 'bool': return bool(node.value)
      case 'addr': return resolveAddr(node.word)
      case 'unary': {
        const v = evalNode(node.operand)
        if (v.t === 'err') return v
        const n = toNumber(v)
        if (n.t === 'err') return n
        return finalizeNumber(node.op === '-' ? -n.v : n.v)
      }
      case 'bin': {
        const l = evalNode(node.left)
        if (l.t === 'err') return l
        const r = evalNode(node.right)
        if (r.t === 'err') return r
        if (node.op === '=' || node.op === '<>' || node.op === '<' || node.op === '<=' || node.op === '>' || node.op === '>=') {
          return compareValues(l, r, node.op)
        }
        const ln = toNumber(l)
        if (ln.t === 'err') return ln
        const rn = toNumber(r)
        if (rn.t === 'err') return rn
        switch (node.op) {
          case '+': return finalizeNumber(ln.v + rn.v)
          case '-': return finalizeNumber(ln.v - rn.v)
          case '*': return finalizeNumber(ln.v * rn.v)
          case '/': return rn.v === 0 ? err('#DIV/0!') : finalizeNumber(ln.v / rn.v)
          case '^': return finalizeNumber(Math.pow(ln.v, rn.v))
        }
        throw new Error('unreachable operator ' + node.op)
      }
      case 'call': return evalCall(node.name, node.args)
      default: throw new Error('unreachable node type ' + node.type)
    }
  }

  return { getCellValue, getFormula }
}

/**
 * Formats a Value for the "values" command: a number rounded to ten
 * significant digits and printed as JavaScript would, TRUE/FALSE for a
 * boolean, the token for an error, and text as itself.
 */
export function formatValue(v) {
  if (v.t === 'num') return formatNumber(v.v)
  if (v.t === 'bool') return v.v ? 'TRUE' : 'FALSE'
  if (v.t === 'err') return v.v
  return v.v
}

function formatNumber(x) {
  if (!Number.isFinite(x)) return x > 0 ? 'Infinity' : x < 0 ? '-Infinity' : 'NaN'
  let rounded = Number(x.toPrecision(10))
  if (Object.is(rounded, -0)) rounded = 0
  return String(rounded)
}

export { numToCol }
"}

