 * Static dependency extraction: lists every cell a formula names directly,
 * without evaluating anything, so both branches of IF and every range
 * endpoint order are named regardless of what they evaluate to.
 */

import { parseAddress, addressKey } from './address.js'
import { parseFormula, GrammarError } from './formula.js'

/**
 * Returns the set of address keys named by a cell's content, or an empty
 * set for a literal or a formula the grammar does not accept.
 */
export function collectDeps(content) {
  const keys = new Set()
  if (!content.startsWith('=')) return keys
  let ast
  try {
    ast = parseFormula(content.slice(1))
  } catch (e) {
    if (e instanceof GrammarError) return keys
    throw e
  }
  walk(ast, keys)
  return keys
}

function addAddr(word, keys) {
  const info = parseAddress(word)
  if (info) keys.add(addressKey(info.col, info.row))
}

function walk(node, keys) {
  switch (node.type) {
    case 'num':
    case 'bool':
      return
    case 'addr':
      addAddr(node.word, keys)
      return
    case 'range': {
      const a = parseAddress(node.a)
      const b = parseAddress(node.b)
      if (!a || !b) return
      const colLo = Math.min(a.col, b.col)
      const colHi = Math.max(a.col, b.col)
      const rowLo = Math.min(a.row, b.row)
      const rowHi = Math.max(a.row, b.row)
      for (let c = colLo; c <= colHi; c++) {
        for (let r = rowLo; r <= rowHi; r++) {
          keys.add(addressKey(c, r))
        }
      }
      return
    }
    case 'unary':
      walk(node.operand, keys)
      return
    case 'bin':
      walk(node.left, keys)
      walk(node.right, keys)
      return
    case 'call':
      for (const a of node.args) walk(a, keys)
      return
    default:
      throw new Error('unreachable node type ' + node.type)
  }
}
"}

