 * The lexer: turns source text into a flat list of tokens, or throws a
 * ScanError carrying the 1-based line/column and reason text the CLI reports.
 */

const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])

const TWO_CHAR_PUNCT = new Set(['==', '!=', '<=', '>=', '&&', '||', '->', '=>'])
const ONE_CHAR_PUNCT = new Set([
  '+', '-', '*', '/', '%', '=', '<', '>', '!', '(', ')', '{', '}', '[', ']', ',', ';', '.',
])

const isLetter = (c) => c !== undefined && /[A-Za-z]/.test(c)
const isDecDigit = (c) => c !== undefined && /[0-9]/.test(c)
const isHexDigit = (c) => c !== undefined && /[0-9a-fA-F]/.test(c)
const isBinDigit = (c) => c === '0' || c === '1'
const isOctDigit = (c) => c !== undefined && /[0-7]/.test(c)
const isIdentStart = (c) => isLetter(c) || c === '_'
const isIdentContinue = (c) => isLetter(c) || isDecDigit(c) || c === '_'

export class ScanError extends Error {
  constructor(line, column, reason) {
    super(reason)
    this.line = line
    this.column = column
    this.reason = reason
  }
}

class Scanner {
  constructor(source) {
    this.chars = Array.from(source)
    this.pos = 0
    this.line = 1
    this.column = 1
  }

  peek(offset = 0) {
    return this.chars[this.pos + offset]
  }

  atEnd() {
    return this.pos >= this.chars.length
  }

  /** Consumes and returns the current code point, updating line/column. */
  advance() {
    const c = this.chars[this.pos]
    this.pos += 1
    if (c === '\n') {
      this.line += 1
      this.column = 1
    } else if (c === '\t') {
      this.column = Math.floor((this.column - 1) / 4) * 4 + 5
    } else {
      this.column += 1
    }
    return c
  }

  error(line, column, reason) {
    return new ScanError(line, column, reason)
  }
}

function scanDigitRun(sc, isDigit) {
  let s = ''
  while (isDigit(sc.peek())) {
    s += sc.advance()
    if (sc.peek() === '_' && isDigit(sc.peek(1))) {
      s += sc.advance()
    }
  }
  return s
}

function scanNumber(sc, startLine, startColumn) {
  let text = ''
  let invalidPrefix = false

  const c0 = sc.peek()
  const c1 = sc.peek(1)
  if (c0 === '0' && (c1 === 'x' || c1 === 'X')) {
    text += sc.advance()
    text += sc.advance()
    const run = scanDigitRun(sc, isHexDigit)
    text += run
    if (run.length === 0) invalidPrefix = true
  } else if (c0 === '0' && (c1 === 'b' || c1 === 'B')) {
    text += sc.advance()
    text += sc.advance()
    const run = scanDigitRun(sc, isBinDigit)
    text += run
    if (run.length === 0) invalidPrefix = true
  } else if (c0 === '0' && (c1 === 'o' || c1 === 'O')) {
    text += sc.advance()
    text += sc.advance()
    const run = scanDigitRun(sc, isOctDigit)
    text += run
    if (run.length === 0) invalidPrefix = true
  } else {
    text += scanDigitRun(sc, isDecDigit)

    if (sc.peek() === '.' && isDecDigit(sc.peek(1))) {
      text += sc.advance()
      text += scanDigitRun(sc, isDecDigit)
    }

    if (sc.peek() === 'e' || sc.peek() === 'E') {
      let signOffset = 1
      let hasSign = false
      if (sc.peek(1) === '+' || sc.peek(1) === '-') {
        signOffset = 2
        hasSign = true
      }
      if (isDecDigit(sc.peek(signOffset))) {
        text += sc.advance()
        if (hasSign) text += sc.advance()
        text += scanDigitRun(sc, isDecDigit)
      }
    }
  }

  if (invalidPrefix || isIdentContinue(sc.peek())) {
    while (isIdentContinue(sc.peek())) {
      text += sc.advance()
    }
    throw sc.error(startLine, startColumn, `invalid number ${text}`)
  }

  return { kind: 'number', line: startLine, column: startColumn, text }
}

function scanEscape(sc) {
  const backslashLine = sc.line
  const backslashColumn = sc.column
  sc.advance() // consume backslash
  const e = sc.peek()

  const simple = { n: '\n', t: '\t', r: '\r', '\\': '\\', '"': '"', '0': '\0' }
  if (e !== undefined && Object.prototype.hasOwnProperty.call(simple, e)) {
    sc.advance()
    return simple[e]
  }

  if (e === 'x') {
    sc.advance()
    const h0 = sc.peek()
    const h1 = sc.peek(1)
    if (isHexDigit(h0) && isHexDigit(h1)) {
      sc.advance()
      sc.advance()
      const code = parseInt(h0 + h1, 16)
      return String.fromCharCode(code)
    }
    throw sc.error(backslashLine, backslashColumn, 'invalid escape \\x')
  }

  if (e === 'u') {
    sc.advance()
    if (sc.peek() === '{') {
      sc.advance()
      let hex = ''
      while (isHexDigit(sc.peek())) {
        hex += sc.advance()
      }
      if (hex.length > 0 && sc.peek() === '}') {
        sc.advance()
        const value = parseInt(hex, 16)
        if (value <= 0x10ffff) {
          return String.fromCodePoint(value)
        }
      }
    }
    throw sc.error(backslashLine, backslashColumn, 'invalid escape \\u')
  }

  throw sc.error(backslashLine, backslashColumn, `invalid escape \\${e ?? ''}`)
}

function scanString(sc, startLine, startColumn) {
  sc.advance() // consume opening quote
  let value = ''
  for (;;) {
    if (sc.atEnd()) {
      throw sc.error(startLine, startColumn, 'unterminated string')
    }
    const c = sc.peek()
    if (c === '"') {
      sc.advance()
      return { kind: 'string', line: startLine, column: startColumn, value }
    }
    if (c === '\n') {
      throw sc.error(sc.line, sc.column, 'newline in string')
    }
    if (c === '\\') {
      value += scanEscape(sc)
      continue
    }
    value += sc.advance()
  }
}

function scanRawString(sc, startLine, startColumn) {
  sc.advance() // 'r'
  sc.advance() // '"'
  let value = ''
  for (;;) {
    if (sc.atEnd()) {
      throw sc.error(startLine, startColumn, 'unterminated string')
    }
    const c = sc.advance()
    if (c === '"') {
      return { kind: 'rawstring', line: startLine, column: startColumn, value }
    }
    value += c
  }
}

function skipBlockComment(sc, startLine, startColumn) {
  sc.advance() // '/'
  sc.advance() // '*'
  let depth = 1
  while (depth > 0) {
    if (sc.atEnd()) {
      throw sc.error(startLine, startColumn, 'unterminated block comment')
    }
    if (sc.peek() === '/' && sc.peek(1) === '*') {
      sc.advance()
      sc.advance()
      depth += 1
    } else if (sc.peek() === '*' && sc.peek(1) === '/') {
      sc.advance()
      sc.advance()
      depth -= 1
    } else {
      sc.advance()
    }
  }
}

function skipLineComment(sc) {
  sc.advance() // '/'
  sc.advance() // '/'
  while (!sc.atEnd() && sc.peek() !== '\n') {
    sc.advance()
  }
}

/** Advances past whitespace and comments, leaving the scanner at the next token or EOF. */
function skipTrivia(sc) {
  for (;;) {
    const c = sc.peek()
    if (c === ' ' || c === '\t' || c === '\r' || c === '\n') {
      sc.advance()
      continue
    }
    if (c === '/' && sc.peek(1) === '/') {
      skipLineComment(sc)
      continue
    }
    if (c === '/' && sc.peek(1) === '*') {
      skipBlockComment(sc, sc.line, sc.column)
      continue
    }
    return
  }
}

function scanPunct(sc, startLine, startColumn) {
  const two = (sc.peek() ?? '') + (sc.peek(1) ?? '')
  if (TWO_CHAR_PUNCT.has(two)) {
    sc.advance()
    sc.advance()
    return { kind: 'punct', line: startLine, column: startColumn, text: two }
  }
  const one = sc.peek()
  if (ONE_CHAR_PUNCT.has(one)) {
    sc.advance()
    return { kind: 'punct', line: startLine, column: startColumn, text: one }
  }
  throw sc.error(startLine, startColumn, `unexpected character ${one}`)
}

function nextToken(sc) {
  skipTrivia(sc)
  if (sc.atEnd()) return null

  const startLine = sc.line
  const startColumn = sc.column
  const c = sc.peek()

  if (c === 'r' && sc.peek(1) === '"') {
    return scanRawString(sc, startLine, startColumn)
  }

  if (isIdentStart(c)) {
    let text = ''
    while (isIdentContinue(sc.peek())) {
      text += sc.advance()
    }
    const kind = KEYWORDS.has(text) ? 'keyword' : 'ident'
    return { kind, line: startLine, column: startColumn, text }
  }

  if (isDecDigit(c)) {
    return scanNumber(sc, startLine, startColumn)
  }

  if (c === '"') {
    return scanString(sc, startLine, startColumn)
  }

  return scanPunct(sc, startLine, startColumn)
}

/** Scans `source` fully, returning the list of tokens, or throwing a ScanError. */
export function tokenize(source) {
