/**
 * The command. `node src/cli.js tokens` prints every token of the source read
 * from standard input with its position, and `node src/cli.js stats` counts the
 * tokens by kind.
 */

import { readFileSync } from 'node:fs'
import { ScanError, tokenize } from './lexer.js'

const STAT_KINDS = ['ident', 'keyword', 'number', 'punct', 'rawstring', 'string']

function tokenBody(token) {
  if (token.kind === 'string' || token.kind === 'rawstring') {
    return JSON.stringify(token.value)
  }
  return token.text
}

function main() {
  const mode = process.argv[2]
  if (mode !== 'tokens' && mode !== 'stats') {
    process.stderr.write('error: usage: cli.js tokens|stats\n')
    process.exit(2)
  }

  const source = readFileSync(0, 'utf8')

  let tokens
  try {
    tokens = tokenize(source)
  } catch (err) {
    if (err instanceof ScanError) {
      process.stderr.write(`error: ${err.line}:${err.column}: ${err.reason}\n`)
      process.exit(2)
    }
    throw err
  }

  if (mode === 'tokens') {
    let out = ''
    for (const token of tokens) {
      out += `${token.line}:${token.column} ${token.kind} ${tokenBody(token)}\n`
    }
    process.stdout.write(out)
  } else {
    const counts = Object.fromEntries(STAT_KINDS.map((k) => [k, 0]))
    for (const token of tokens) counts[token.kind] += 1
    let out = ''
    for (const kind of STAT_KINDS) out += `${kind} ${counts[kind]}\n`
    out += `total ${tokens.length}\n`
    process.stdout.write(out)
  }
}

main()
"}

