{"file_path":"src/uri.js","content":"/**
 * URI reference parsing, normalization and resolution per RFC 3986's
 * generic syntax (section 3) and its normalization (6.2.2) and reference
 * resolution (5.2) algorithms, as narrowed by the task specification.
 */

const DEFAULT_PORTS = { http: '80', ws: '80', https: '443', wss: '443', ftp: '21' }

/** Signals a `%` not followed by two hex digits in the named component. */
export class ComponentError extends Error {
  constructor(component) {
    super(`the ${component} has a truncated percent-encoding`)
    this.component = component
  }
}

/** Signals that a resolve base carries no scheme. */
export class BaseNoSchemeError extends Error {
  constructor() {
    super('the base has no scheme')
  }
}

function asciiLower(s) {
  return s.replace(/[A-Z]/g, (c) => String.fromCharCode(c.charCodeAt(0) + 32))
}

/**
 * Splits a URI reference into its five generic components. Absent
 * components are `null`; present-but-empty ones are `''`.
 */
export function parseReference(s) {
  let rest = s
  let scheme = null
  let colonIdx = -1
  for (let i = 0; i < rest.length; i++) {
    const c = rest[i]
    if (c === ':') {
      colonIdx = i
      break
    }
    if (c === '/' || c === '?' || c === '#') break
  }
  if (colonIdx !== -1) {
    scheme = rest.slice(0, colonIdx)
    rest = rest.slice(colonIdx + 1)
  }

  let authority = null
  if (rest.startsWith('//')) {
    rest = rest.slice(2)
    let end = rest.length
    for (let i = 0; i < rest.length; i++) {
      const c = rest[i]
      if (c === '/' || c === '?' || c === '#') {
        end = i
        break
      }
    }
    authority = rest.slice(0, end)
    rest = rest.slice(end)
  }

  let pathEnd = rest.length
  for (let i = 0; i < rest.length; i++) {
    const c = rest[i]
    if (c === '?' || c === '#') {
      pathEnd = i
      break
    }
  }
  const path = rest.slice(0, pathEnd)
  rest = rest.slice(pathEnd)

  let query = null
  if (rest.startsWith('?')) {
    rest = rest.slice(1)
    let qEnd = rest.length
    for (let i = 0; i < rest.length; i++) {
      if (rest[i] === '#') {
        qEnd = i
        break
      }
    }
    query = rest.slice(0, qEnd)
    rest = rest.slice(qEnd)
  }

  let fragment = null
  if (rest.startsWith('#')) {
    fragment = rest.slice(1)
  }

  return { scheme, authority, path, query, fragment }
}

/**
 * Splits an authority string into userinfo, host and port, following the
 * task's `@`/`]`/`:` boundary rules. `authority` must not be `null`.
 */
export function parseAuthority(authority) {
  let userinfo = null
  let rest = authority
  const atIdx = authority.lastIndexOf('@')
  if (atIdx !== -1) {
    userinfo = authority.slice(0, atIdx)
    rest = authority.slice(atIdx + 1)
  }

  const bracketIdx = rest.lastIndexOf(']')
  const colonIdx = rest.indexOf(':', bracketIdx + 1)
  let host, port
  if (colonIdx !== -1) {
    host = rest.slice(0, colonIdx)
    port = rest.slice(colonIdx + 1)
  } else {
    host = rest
    port = null
  }

  return { userinfo, host, port }
}

function buildAuthority(userinfo, host, port) {
  return (userinfo !== null ? userinfo + '@' : '') + host + (port !== null ? ':' + port : '')
}

function buildReference({ scheme, authority, path, query, fragment }) {
  return (
    (scheme !== null ? scheme + ':' : '') +
    (authority !== null ? '//' + authority : '') +
    path +
    (query !== null ? '?' + query : '') +
    (fragment !== null ? '#' + fragment : '')
  )
}

function isUnreservedByte(code) {
  return (
    (code >= 0x41 && code <= 0x5a) || // A-Z
    (code >= 0x61 && code <= 0x7a) || // a-z
    (code >= 0x30 && code <= 0x39) || // 0-9
    code === 0x2d || // -
    code === 0x2e || // .
    code === 0x5f || // _
    code === 0x7e // ~
  )
}

/**
 * Uppercases the hex digits of each `%XX` triplet in `s`, then decodes it
 * when the encoded byte is an unreserved character. Throws ComponentError
 * for `componentName` when a `%` is not followed by two hex digits.
 */
export function normalizePercentEncoding(s, componentName) {
  let result = ''
  for (let i = 0; i < s.length; i++) {
    const c = s[i]
    if (c === '%') {
      const hex = s.slice(i + 1, i + 3)
      if (hex.length < 2 || !/^[0-9A-Fa-f]{2}$/.test(hex)) {
        throw new ComponentError(componentName)
      }
      const upper = hex.toUpperCase()
      const code = parseInt(upper, 16)
      if (isUnreservedByte(code)) {
        result += String.fromCharCode(code)
      } else {
        result += '%' + upper
      }
      i += 2
    } else {
      result += c
    }
  }
  return result
}

/** Removes dot segments from `path` per RFC 3986 section 5.2.4. */
export function removeDotSegments(path) {
  let input = path
  let output = ''
  while (input.length > 0) {
    if (input.startsWith('../')) {
      input = input.slice(3)
    } else if (input.startsWith('./')) {
      input = input.slice(2)
    } else if (input.startsWith('/./')) {
      input = '/' + input.slice(3)
    } else if (input === '/.') {
      input = '/'
    } else if (input.startsWith('/../')) {
      input = '/' + input.slice(4)
      output = removeLastSegment(output)
    } else if (input === '/..') {
      input = '/'
      output = removeLastSegment(output)
    } else if (input === '.' || input === '..') {
      input = ''
    } else {
      let idx
      if (input[0] === '/') {
        idx = 1
        while (idx < input.length && input[idx] !== '/') idx++
      } else {
        idx = 0
        while (idx < input.length && input[idx] !== '/') idx++
      }
      output += input.slice(0, idx)
      input = input.slice(idx)
    }
  }
  return output
}

function removeLastSegment(output) {
  const idx = output.lastIndexOf('/')
  return idx === -1 ? '' : output.slice(0, idx)
}

function isDefaultPort(scheme, port) {
  return scheme !== null && DEFAULT_PORTS[scheme] === port
}

/**
 * Normalizes a parsed reference's components, applying, in order: scheme
 * case-folding, percent-encoding normalization (checked path, userinfo,
 * host, query, fragment for truncation), host case-folding, default-port
 * removal, dot-segment removal, and the empty-path-with-authority rule.
 */
export function normalizeParsed({ scheme, authority, path, query, fragment }) {
  const normScheme = scheme !== null ? asciiLower(scheme) : null

  const hasAuthority = authority !== null
  let userinfo = null
  let host = ''
  let port = null
  if (hasAuthority) {
    ;({ userinfo, host, port } = parseAuthority(authority))
  }

  const normPath = normalizePercentEncoding(path, 'path')
  const normUserinfo = userinfo !== null ? normalizePercentEncoding(userinfo, 'userinfo') : null
  const normHost = normalizePercentEncoding(host, 'host')
  const normQuery = query !== null ? normalizePercentEncoding(query, 'query') : null
  const normFragment = fragment !== null ? normalizePercentEncoding(fragment, 'fragment') : null

  const lowerHost = asciiLower(normHost)

  let normPort = port
  if (normPort !== null && (normPort === '' || isDefaultPort(normScheme, normPort))) {
    normPort = null
  }

  let normDotPath = removeDotSegments(normPath)
  if (hasAuthority && normDotPath === '') {
    normDotPath = '/'
  }

  const normAuthority = hasAuthority ? buildAuthority(normUserinfo, lowerHost, normPort) : null

  return { scheme: normScheme, authority: normAuthority, path: normDotPath, query: normQuery, fragment: normFragment }
}

/** Parses, normalizes and reassembles a URI reference. */
export function normalize(ref) {
  return buildReference(normalizeParsed(parseReference(ref)))
}

function mergePaths(base, refPath) {
  if (base.authority !== null && base.path === '') {
    return '/' + refPath
  }
  const idx = base.path.lastIndexOf('/')
  if (idx === -1) return refPath
  return base.path.slice(0, idx + 1) + refPath
}

/**
 * Resolves reference `ref` against base `base` per RFC 3986 section 5.2.2's
 * strict transform, then normalizes the result.
 */
export function resolve(base, ref) {
  const B = parseReference(base)
  if (B.scheme === null) {
    throw new BaseNoSchemeError()
  }
  const R = parseReference(ref)

  const T = {}
  if (R.scheme !== null) {
    T.scheme = R.scheme
    T.authority = R.authority
    T.path = removeDotSegments(R.path)
    T.query = R.query
  } else if (R.authority !== null) {
    T.scheme = B.scheme
    T.authority = R.authority
    T.path = removeDotSegments(R.path)
    T.query = R.query
  } else if (R.path === '') {
    T.scheme = B.scheme
    T.authority = B.authority
    T.path = B.path
