const NAME_CHAR = /[A-Za-z0-9_-]/
const INTEGER_RE = /^[+-]?\d+(_\d+)*$/
const FLOAT_RE = /^[+-]?\d+(_\d+)*(\.\d+(_\d+)*)?([eE][+-]?\d+(_\d+)*)?$/

/**
 * A cursor over one input line, producing the tokens a directive is built
 * from: names, dotted names, and values (including nested arrays and inline
 * tables). Nothing here spans multiple lines, since every directive fits on
 * one line per the format.
 */
export class LineParser {
  constructor(line, lineNo) {
    this.line = line
    this.lineNo = lineNo
    this.pos = 0
  }

  err(reason) {
    throw new ParseError(this.lineNo, reason)
  }

  eof() {
    return this.pos >= this.line.length
  }

  peek() {
    return this.line[this.pos]
  }

  skipWS() {
    while (!this.eof() && (this.peek() === ' ' || this.peek() === '\t')) this.pos++
  }

  /** True when the rest of the line is empty or an unquoted comment. */
  atCommentOrEOL() {
    if (this.eof()) return true
    const c = this.peek()
    return c === '#' || c === ';'
  }

  readBasicString() {
    this.pos++ // opening "
    let out = ''
    for (;;) {
      if (this.eof()) this.err('unterminated string')
      const c = this.line[this.pos]
      if (c === '"') {
        this.pos++
        return out
      }
      if (c === '\\') {
        this.pos++
        if (this.eof()) this.err('unterminated string')
        const e = this.line[this.pos]
        if (e === '"') { out += '"'; this.pos++ }
        else if (e === '\\') { out += '\\'; this.pos++ }
        else if (e === 'n') { out += '\n'; this.pos++ }
        else if (e === 't') { out += '\t'; this.pos++ }
        else if (e === 'r') { out += '\r'; this.pos++ }
        else if (e === '0') { out += '\0'; this.pos++ }
        else if (e === 'u') {
          const hex = this.line.slice(this.pos + 1, this.pos + 5)
          if (!/^[0-9A-Fa-f]{4}$/.test(hex)) this.err('invalid escape \\u')
          out += String.fromCharCode(parseInt(hex, 16))
          this.pos += 5
        } else {
          this.err('invalid escape \\' + e)
        }
      } else {
        out += c
        this.pos++
      }
    }
  }

  readLiteralString() {
    this.pos++ // opening '
    let out = ''
    for (;;) {
      if (this.eof()) this.err('unterminated string')
      const c = this.line[this.pos]
      if (c === "'") {
        this.pos++
        return out
      }
      out += c
      this.pos++
    }
  }

  /** A bare word or quoted string, decoded to its text. */
  readName() {
    this.skipWS()
    if (this.eof()) this.err('expected a name')
    const c = this.peek()
    if (c === '"') return this.readBasicString()
    if (c === "'") return this.readLiteralString()
    const start = this.pos
    while (!this.eof() && NAME_CHAR.test(this.peek())) this.pos++
    if (this.pos === start) this.err('expected a name')
    return this.line.slice(start, this.pos)
  }

  /** Names joined by `.`, with surrounding whitespace allowed. */
  readDottedName() {
    const segments = [this.readName()]
    for (;;) {
      this.skipWS()
      if (this.peek() !== '.') break
      this.pos++
      this.skipWS()
      segments.push(this.readName())
    }
    return segments
  }

  /**
   * A value, tagged with its kind. `path` is the absolute path (as decoded
   * name segments) the value is being assigned to, threaded through so
   * nested tables know their own location for error messages.
   */
  readValue(path) {
    this.skipWS()
    if (this.atCommentOrEOL() || this.peek() === ',' || this.peek() === ']' || this.peek() === '}') {
      this.err('expected a value')
