{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e3-attempts-t5-20260919T123108Z/cell-yR3KXd/src/render.js","content":"/** Ascending order by UTF-16 code unit, which matches code point order within the BMP. */
function sortedKeys(map) {
  return Array.from(map.keys()).sort()
}

function typeName(node) {
  if (node.kind === 'array-of-tables') return 'array'
  return node.kind
}

function indent(depth) {
  return '  '.repeat(depth)
}

function valueToJson(node, depth) {
  switch (node.kind) {
    case 'table': {
      const keys = sortedKeys(node.map)
      if (keys.length === 0) return '{}'
      const body = keys
        .map((k) => `${indent(depth + 1)}${JSON.stringify(k)}: ${valueToJson(node.map.get(k), depth + 1)}`)
        .join(',\n')
      return `{\n${body}\n${indent(depth)}}`
    }
    case 'array-of-tables':
    case 'array': {
      const items = node.kind === 'array-of-tables' ? node.items : node.items
      if (items.length === 0) return '[]'
      const body = items.map((v) => `${indent(depth + 1)}${valueToJson(v, depth + 1)}`).join(',\n')
      return `[\n${body}\n${indent(depth)}]`
    }
    case 'string':
      return JSON.stringify(node.value)
    case 'integer':
    case 'float':
      return JSON.stringify(node.value)
    case 'boolean':
      return node.value ? 'true' : 'false'
    default:
      throw new Error('unreachable node kind ' + node.kind)
  }
}

/** Render the parsed document as indented, key-sorted JSON with a trailing newline. */
export function toJson(root) {
  return valueToJson(root, 0) + '\n'
}

/** Render one `<path> <type>` line per node below the root, depth first. */
export function toKeys(root) {
  const lines = []
  walkKeys(root, '', lines)
  return lines.join('')
}

function walkKeys(node, path, lines) {
  if (node.kind === 'table') {
    for (const key of sortedKeys(node.map)) {
      const child = node.map.get(key)
      const childPath = path === '' ? key : `${path}.${key}`
      lines.push(`${childPath} ${typeName(child)}\n`)
      walkKeys(child, childPath, lines)
    }
  } else if (node.kind === 'array' || node.kind === 'array-of-tables') {
    node.items.forEach((child, i) => {
      const childPath = `${path}[${i}]`
      lines.push(`${childPath} ${typeName(child)}\n`)
      walkKeys(child, childPath, lines)
    })
  }
}
