      const child = node.map.get(key)
      const childPath = path === '' ? key : `${path}.${key}`
      lines.push(`${childPath} ${typeName(child)}\n`)
      walkKeys(child, childPath, lines)
    }
  } else if (node.kind === 'array' || node.kind === 'array-of-tables') {
    node.items.forEach((child, i) => {
      const childPath = `${path}[${i}]`
      lines.push(`${childPath} ${typeName(child)}\n`)
      walkKeys(child, childPath, lines)
    })
  }
}
